import os, sys, pty, time, select, fcntl, termios, struct

def run(args, keys=b"", rows=30, cols=120, wait=1.0, env=None, post_wait=0.35, exit=True, exe='/workspace/executable'):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        e['TERM'] = 'xterm-256color'
        e['LINES'] = str(rows); e['COLUMNS'] = str(cols)
        if env: e.update(env)
        os.execvpe(exe, [exe]+args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b""
    def drain(t):
        nonlocal out
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.05)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: return False
                if not d: return False
                out += d
        return True
    drain(wait)
    for k in keys:
        os.write(fd, bytes([k]))
        drain(post_wait)
    if exit:
        os.write(fd, b'q')
        drain(0.6)
    return out

def main():
    argv = sys.argv[1:]
    a = {}
    exe = os.environ.get('BIN','/workspace/executable')
    keys = b''
    rows, cols, wait, pw = 30, 120, 1.0, 0.35
    raw = False
    while argv:
        x = argv.pop(0)
        if x == '--keys': keys = argv.pop(0).encode().decode('unicode_escape').encode('latin1')
        elif x == '--rows': rows = int(argv.pop(0))
        elif x == '--cols': cols = int(argv.pop(0))
        elif x == '--wait': wait = float(argv.pop(0))
        elif x == '--pw': pw = float(argv.pop(0))
        elif x == '--raw': raw = True
        elif x == '--exe': exe = argv.pop(0)
        elif x == '--': break
        else: argv.insert(0, x); break
    o = run(argv, keys, rows, cols, wait, post_wait=pw, exit=not raw, exe=exe)
    sys.stdout.buffer.write(o if raw else o.replace(b'\x1b',b'<ESC>'))
if __name__ == '__main__':
    main()
