{"command": "cat <<'EOF' > $HOME/h/ht.py
import os, sys, pty, time, select, fcntl, termios, struct, re

KEYMAP = {
 'up':b'\033[A','down':b'\033[B','right':b'\033[C','left':b'\033[D',
 'F1':b'\033OP','F2':b'\033OQ','F3':b'\033OR','F4':b'\033OS','F5':b'\033[15~','F6':b'\033[17~',
 'F7':b'\033[18~','F8':b'\033[19~','F9':b'\033[20~','F10':b'\033[21~',
 'esc':b'\033','tab':b'\t','stab':b'\033[Z','enter':b'\r','space':b' ','pgup':b'\033[5~','pgdn':b'\033[6~',
 'home':b'\033[H','end':b'\033[F','ins':b'\033[2~','del':b'\033[3~','ctrl-c':b'\003','ctrl-d':b'\004',
}
def parse_keys(spec):
    out=[]
    i=0
    while i < len(spec):
        if spec.startswith('{{', i):
            j=spec.index('}}',i)
            tok=spec[i+2:j]; i=j+2
            out.append(KEYMAP.get(tok, tok.encode()))
        else:
            out.append(spec[i].encode()); i+=1
    return out

def run(args, keyspec='', rows=30, cols=120, wait=1.2, env=None, post_wait=0.3, exit=True, exe='/workspace/executable'):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        e['TERM'] = 'xterm-256color'
        e['LINES'] = str(rows); e['COLUMNS'] = str(cols)
        if env: e.update(env)
        os.execvpe(exe, [exe]+args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b""
    def drain(t):
        nonlocal out
        end = time.time()+t
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.05)
            if r:
                try: d = os.read(fd, 65536)
                except OSError: return False
                if not d: return False
                out += d
        return True
    drain(wait)
    for k in parse_keys(keyspec):
        os.write(fd, k)
        drain(post_wait)
    if exit:
        os.write(fd, b'q')
        drain(0.5)
    return out

def render(data, rows=30, cols=120):
    # naive ANSI screen emulator producing plain text
    scr=[[' ']*cols for _ in range(rows)]
    r=c=0; bold=0
    i=0
    seq=re.compile(rb'\x1b\[([0-9;?<>=]*)([A-Za-z])')
    while i < len(data):
        m=seq.match(data,i)
        if m:
            p=m.group(1).decode(); f=m.group(2).decode()
            i=m.end()
            nums=[int(x) for x in p.replace('?','').split(';') if x.isdigit()]
            if f=='H':
                r=(nums[0]-1) if len(nums)>0 else 0
                c=(nums[1]-1) if len(nums)>1 else 0
            elif f=='d': r=(nums[0]-1) if nums else 0
            elif f=='G': c=(nums[0]-1) if nums else 0
            elif f=='J':
                if not nums or nums[0]==0:
                    for cc in range(c,cols): scr[r][cc]=' '
                    for rr in range(r+1,rows): scr[rr]=[' ']*cols
                elif nums[0]==2:
                    for rr in range(rows): scr[rr]=[' ']*cols
            elif f=='K':
                for cc in range(c,cols): scr[r][cc]=' '
            elif f=='X':
                n=nums[0] if nums else 1
                for cc in range(c,min(cols,c+n)): scr[r][cc]=' '
                c=min(cols,c+n)
            elif f=='C': c=min(cols-1,c+(nums[0] if nums else 1))
            elif f=='D': c=max(0,c-(nums[0] if nums else 1))
            elif f=='A': r=max(0,r-(nums[0] if nums else 1))
            elif f=='B': r=min(rows-1,r+(nums[0] if nums else 1))
            elif f=='b':
                n=nums[0] if nums else 1
                ch=scr[r][c-1] if c>0 else ' '
                for _ in range(n):
                    if c<cols: scr[r][c]=ch; c+=1
            continue
        b=data[i]
        if b==0x1b:
            if data[i:i+2]==b'\x1b(B' or data[i:i+2]==b'\x1b)B' or data[i:i+3]==b'\x1b(B': i+=3; continue
            j=i
            while j<len(data) and data[j] not in b'ABCDHJKdGmXb' : j+=1
            if j<len(data): i=j+1
            else: i=j
            continue
        if b==0x0d: c=0; i+=1; continue
        if b==0x0a: r+=1; c=0; i+=1; continue
        if b==0x08: c=max(0,c-1); i+=1; continue
        ch=chr(b)
        if 0x1b <= b < 0x20: i+=1; continue
        if c>=cols: c=cols-1
        if r<rows: scr[r][c]=ch
        c+=1; i+=1
    return '\n'.join(''.join(x).rstrip() for x in scr)

def main():
    argv=sys.argv[1:]; exe='/workspace/executable'
    keyspec=''; rows=30; cols=120; wait=1.2; pw=0.3; mode='text'
    while argv and argv[0].startswith('~'):
        x=argv.pop(0)
        if x=='~keys': keyspec=argv.pop(0)
        elif x=='~rows': rows=int(argv.pop(0))
        elif x=='~cols': cols=int(argv.pop(0))
        elif x=='~wait': wait=float(argv.pop(0))
        elif x=='~pw': pw=float(argv.pop(0))
        elif x=='~exe': exe=argv.pop(0)
        elif x=='~raw': mode='raw'
        elif x=='~full': mode='full'
    if mode=='raw':
        sys.stdout.buffer.write(run(argv,keyspec,rows,cols,wait,post_wait=pw,exit=False,exe=exe).replace(b'\x1b',b'<ESC>'))
    elif mode=='full':
        sys.stdout.buffer.write(run(argv,keyspec,rows,cols,wait,post_wait=pw,exit=False,exe=exe))
    else:
        print(render(run(argv,keyspec,rows,cols,wait,post_wait=pw,exit=False,exe=exe),rows,cols))
if __name__=='__main__':
    main()
