import os, sys, subprocess, time, shlex
KEYMAP = {
 'up':b'\033[A','down':b'\033[B','right':b'\033[C','left':b'\033[D',
 'F1':b'\033OP','F2':b'\033OQ','F3':b'\033OR','F4':b'\033OS','F5':b'\033[15~','F6':b'\033[17~',
 'F7':b'\033[18~','F8':b'\033[19~','F9':b'\033[20~','F10':b'\033[21~',
 'esc':b'\033','tab':b'\t','stab':b'\033[Z','enter':b'\r','space':b' ','pgup':b'\033[5~','pgdn':b'\033[6~',
 'home':b'\033[H','end':b'\033[F','del':b'\033[3~','ctrl-c':b'\003','ctrl-d':b'\004','ctrl-a':b'\001',
}
def parse(spec):
    out=[]; i=0
    while i<len(spec):
        if spec.startswith('{{',i):
            j=spec.index('}}',i); tok=spec[i+2:j]; i=j+2
            out.append(KEYMAP.get(tok,tok.encode()))
        else:
            out.append(spec[i].encode()); i+=1
    return out
def run(argv, exe, rows, cols, name, wait, keys, pw, env=None):
    subprocess.run(['tmux','kill-session','-t',name],capture_output=True)
    cmd=['tmux','new-session','-d','-x',str(cols),'-y',str(rows),'-s',name]
    cmd+=['-e','TERM=xterm-256color']
    for k,v in (env or {}).items(): cmd+=['-e','%s=%s'%(k,v)]
    cmd+= [exe]+argv
    subprocess.run(cmd,capture_output=True)
    time.sleep(wait)
    for k in keys:
        subprocess.run(['tmux','send-keys','-t',name,'-l',k.decode('latin1')],capture_output=True)
        time.sleep(pw)
def main():
    argv=sys.argv[1:]; exe=os.environ.get('BIN','/workspace/executable')
    keyspec=''; rows=30; cols=120; wait=1.5; pw=0.3; mode='text'; name='s0'; env={}
    i=0
    while i<len(argv):
        x=argv[i]
        if x.startswith('~'):
            if x=='~keys': keyspec=argv[i+1]
            elif x=='~rows': rows=int(argv[i+1])
            elif x=='~cols': cols=int(argv[i+1])
            elif x=='~wait': wait=float(argv[i+1])
            elif x=='~pw': pw=float(argv[i+1])
            elif x=='~exe': exe=argv[i+1]
            elif x=='~raw': mode='raw'
            elif x=='~name': name=argv[i+1]
            elif x=='~env': k,v=argv[i+1].split('=',1); env[k]=v
            argv.pop(i+1); argv.pop(i)
        else: i+=1
    run(argv,exe,rows,cols,name,wait,parse(keyspec),pw,env)
    if mode=='raw':
        o=subprocess.run(['tmux','capture-pane','-t',name,'-p','-e'],capture_output=True,text=True)
        sys.stdout.write(o.stdout.replace('\x1b','<ESC>'))
    else:
        o=subprocess.run(['tmux','capture-pane','-t',name,'-p'],capture_output=True,text=True)
        sys.stdout.write(o.stdout)
if __name__=='__main__': main()
