#include "htop.h"

int fieldIndexByName(const char* name) {
   for (int i = 0; i < N_FIELDS; i++)
      if (strcmp(fieldTable[i].name, name) == 0) return i;
   return -1;
}

void fieldPrintSortHelp(void) {
   for (int i = 0; i < N_FIELDS; i++)
      printf("%19s %s\n", fieldTable[i].name, fieldTable[i].description);
}

/* Pad a right aligned title into width */
static void fieldTitleAligned(const FieldInfo* f, char* buf, int bufn) {
   int len = (int)strlen(f->title);
   int off = f->align == ALIGN_RIGHT ? (f->width > len ? f->width - len : 0) : 0;
   for (int i = 0; i < off && i < bufn - 1; i++) buf[i] = ' ';
   strncpy(buf + off, f->title, bufn - 1 - off);
   buf[bufn - 1] = '\0';
}

/* Legacy numeric ids for the settings file, in the order htop's own enum lists them. */
