static char* xstrdup(const char* s) {
   if (!s) return NULL;
   size_t n = strlen(s);
   char* r = malloc(n + 1);
   memcpy(r, s, n + 1);
   return r;
}

static void setStr(char** slot, const char* s) {
   free(*slot);
   *slot = s ? xstrdup(s) : NULL;
}

static uid_t myUid = 0;
static char* myUserName = NULL;
static char* myUserStr = NULL;

static void initUser(void) {
   myUid = getuid();
   struct passwd* pw = getpwuid(myUid);
   char buf[32];
   if (pw && pw->pw_name) {
      myUserName = xstrdup(pw->pw_name);
      xSnprintf(buf, sizeof(buf), "%s", pw->pw_name);
   } else {
      xSnprintf(buf, sizeof(buf), "%d", (int)myUid);
   }
   myUserStr = xstrdup(buf);
}

/* ---- /proc reading ---- */

static bool readFileStr(const char* path, char* buf, size_t n) {
   int fd = open(path, O_RDONLY);
   if (fd < 0) return false;
   ssize_t r = read(fd, buf, n - 1);
   close(fd);
   if (r <= 0) { buf[0] = '\0'; return false; }
   buf[r] = '\0';
