/* ---- rendering helpers ---- */

static void rstrip(char* s) { size_t n = strlen(s); while (n && s[n-1] == ' ') s[--n] = '\0'; }

/* print a human readable byte count like htop's Meter_humanUnit */
void printHumanSize(char* buf, int n, double v) {
   const char* units[] = { "B", "K", "M", "G", "T", "P", "E" };
   int unit = 0;
   while (v >= 1024.0 && unit < 6) { v /= 1024.0; unit++; }
   if (unit == 0) snprintf(buf, n, "%d%s", (int)v, units[unit]);
   else if (v >= 100) snprintf(buf, n, "%.0f%s", v, units[unit]);
   else if (v >= 10) snprintf(buf, n, "%.1f%s", v, units[unit]);
   else snprintf(buf, n, "%.2f%s", v, units[unit]);
}

/* format like htop's Process_printRate: "12.34 M/s" */
static void printRate(char* buf, int n, double v) {
   if (v <= 0) { snprintf(buf, n, "0.00 B/s"); return; }
   char s[32];
   printHumanSize(s, sizeof(s), v);
   snprintf(buf, n, "%s/s", s);
}

static void printTime(char* buf, int n, u64 totalHundredths) {
   u64 totalSeconds = totalHundredths / 100;
   u64 hh = totalSeconds / 3600;
   u64 mm = (totalSeconds / 60) % 60;
   u64 ss = totalSeconds % 60;
   u64 hs = totalHundredths % 100;
   if (hh >= 100) {
      u64 dd = hh / 24;
      hh %= 24;
      snprintf(buf, n, "%lldd%02lld:%02lld", (long long)dd, (long long)hh, (long long)mm);
   } else if (hh > 0) {
      snprintf(buf, n, "%lld:%02llu", (long long)hh, mm);
   } else if (mm >= 100) {
      snprintf(buf, n, "%3llu:%02llu", mm, ss);
   } else {
      snprintf(buf, n, "%2llu:%02llu.%02llu", mm, ss, hs);
   }
}

static void printTimeLong(char* buf, int n, u64 totalHundredths) {
   u64 totalSeconds = totalHundredths / 100;
   u64 hh = totalSeconds / 3600;
   u64 mm = (totalSeconds / 60) % 60;
   u64 ss = totalSeconds % 60;
   if (hh > 0) snprintf(buf, n, "%2lluh%02llu:%02llu", hh, mm, ss);
   else snprintf(buf, n, "%02llu:%02llu", mm, ss);
}

static void printElapsed(char* buf, int n, u64 totalHundredths) {
   printTimeLong(buf, n, totalHundredths);
}

static void printStartTime(char* buf, int n, u64 starttimeTicks) {
   time_t start = PL.bootTime + (time_t)(starttimeTicks / (u64)PL.clockTicks);
   time_t now = time(NULL);
   if (now - start < 86400) {
      struct tm lt; localtime_r(&start, &lt);
      snprintf(buf, n, "%2d:%02d", lt.tm_hour, lt.tm_min);
   } else if (now - start < 86400L * 365) {
      struct tm lt; localtime_r(&start, &lt);
      strftime(buf, n, "%b %e", &lt);
      rstrip(buf);
   } else {
      struct tm lt; localtime_r(&start, &lt);
      strftime(buf, n, "%Y", &lt);
   }
}
CEOF
echo ok"}

