/* ---- field values ---- */

static const char* stateColor(Process* p) {
   switch (p->state) {
      case 'R': return "\033[32m";
      case 'S': return "\033[36m";
      case 'D': return "\033[33m";
      case 'Z': return "\033[31m";
      case 'T': return "\033[36m";
      case 'W': return "\033[36m";
      case 'I': return "\033[33m";
      default: return "";
   }
}

static void fmtNum(char* buf, int n, int width, u64 v) {
   if (v == 0)
      snprintf(buf, n, "%*s ", width, "0");
   else {
      char tmp[32];
      snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
      snprintf(buf, n, "%*s ", width, tmp);
   }
}

/* color a number: the part above the last 3 digits is drawn in the megabyte color */
static void drawColoredNumber(int width, u64 v) {
   char tmp[32];
   snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
   int len = (int)strlen(tmp);
   if (len > width) len = width;
   char buf[40];
   int pad = width - len;
   if (pad > 0) {
      snprintf(buf, sizeof(buf), "%*s", pad, "");
      attrset(CRT_color(COLOR_PROCESS));
      addstr(buf);
   }
   if (v >= 1000) {
      int lead = len - 3;
      if (lead > 0) {
         char leadbuf[8];
         snprintf(leadbuf, sizeof(leadbuf), "%.*s", lead, tmp);
         attrset(CRT_color(COLOR_PROCESS_COMM));
         addstr(leadbuf);
      }
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp + lead);
   } else {
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

static void drawStr(const char* s, int width, bool leftAlign) {
   char buf[1024];
   int len = (int)strlen(s);
   if (leftAlign) {
      snprintf(buf, sizeof(buf), "%-*s ", width, s);
   } else {
      snprintf(buf, sizeof(buf), "%*s ", width, s);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
}

static void drawPct(int width, double v) {
   char buf[32];
   snprintf(buf, sizeof(buf), "%*.*f", width, 1, v);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

void Process_writeField(Process* p, ProcessField field) {
   char buf[1024];
   switch (field) {
      case PID: {
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[PID].width, p->pid);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(buf);
         break;
      }
      case COMMAND: {
         const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
         attrset(CRT_color(COLOR_PROCESS));
         if (PL.settings->showProgramPath && cmd[0] != '\0') {
            /* basename coloring */
            const char* base = strrchr(cmd, '/');
            if (PL.settings->highlightBaseName && base && base[1]) {
               int n = (int)(base + 1 - cmd);
               addnstr(cmd, n);
               attrset(CRT_color(COLOR_PROCESS_BASENAME));
               addstr(base + 1);
            } else if (base && base[1] && !PL.settings->showProgramPath) {
               addstr(base + 1);
            } else {
               addstr(cmd);
            }
         } else if (cmd[0] != '\0') {
            addstr(cmd);
         } else {
            addstr(p->comm ? p->comm : "");
         }
         break;
      }
      case STATE: {
         const char* color = NULL;
         switch (p->state) {
            case 'R': color = "\033[0;1m\033[32m"; break;
            case 'S': color = "\033[0;1m\033[90m"; break;
            case 'D': color = "\033[0;1m\033[33m"; break;
            case 'Z': color = "\033[0;1m\033[31m"; break;
            case 'T': color = "\033[0;1m\033[36m"; break;
            case 'W': color = "\033[0;1m\033[36m"; break;
            case 'I': color = "\033[0;1m\033[33m"; break;
            default: color = "\033[0;1m\033[90m"; break;
         }
         fputs(color, stdout);
         snprintf(buf, sizeof(buf), "%c ", p->state);
         addstr(buf);
         break;
      }
      case PPID: fmtNum(buf, sizeof(buf), fieldTable[PPID].width, (u64)p->ppid); attrset(0); addstr(buf); break;
      case PGRP: fmtNum(buf, sizeof(buf), fieldTable[PGRP].width, (u64)p->pgrp); attrset(0); addstr(buf); break;
      case SESSION: fmtNum(buf, sizeof(buf), fieldTable[SESSION].width, (u64)p->session); attrset(0); addstr(buf); break;
      case TTY: drawStr(p->tty, fieldTable[TTY].width, true); break;
      case TPGID: fmtNum(buf, sizeof(buf), fieldTable[TPGID].width, (u64)p->tpgid); attrset(0); addstr(buf); break;
      case MINFLT: drawColoredNumber(fieldTable[MINFLT].width, p->minflt); break;
      case CMINFLT: drawColoredNumber(fieldTable[CMINFLT].width, p->cminflt); break;
      case MAJFLT: drawColoredNumber(fieldTable[MAJFLT].width, p->majflt); break;
      case CMAJFLT: drawColoredNumber(fieldTable[CMAJFLT].width, p->cmajflt); break;
      case UTIME:
      case STIME:
      case CUTIME:
      case CSTIME:
      case TIME: {
         u64 total = 0;
         if (field == UTIME) total = p->utime;
         else if (field == STIME) total = p->stime;
         else if (field == CUTIME) total = p->cutime;
         else if (field == CSTIME) total = p->cstime;
         else total = p->utime + p->stime;
         u64 hundredths = total * 100 / (u64)PL.clockTicks;
         printTime(buf, sizeof(buf), hundredths);
         snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " ");
         char padded[64];
         snprintf(padded, sizeof(padded), "%*s", fieldTable[field].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(padded);
         break;
      }
      case PRIORITY: fmtNum(buf, sizeof(buf), fieldTable[PRIORITY].width, (u64)p->priority); attrset(0); addstr(buf); break;
      case NICE: {
         int color = p->nice > 0 ? EX_NICE_LOW : (p->nice < 0 ? EX_NICE_HIGH : COLOR_PROCESS);
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[NICE].width, p->nice);
         attrset(CRT_color(color));
         addstr(buf);
         break;
      }
      case STARTTIME: {
         printStartTime(buf, sizeof(buf), p->starttime);
         int len = (int)strlen(buf);
         char pad[32];
         int w = fieldTable[STARTTIME].width;
         if (len < w) { memset(pad, ' ', w - len); pad[w-len] = '\0'; }
         else pad[0] = '\0';
         char full[64];
         snprintf(full, sizeof(full), "%s%s ", pad, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case PROCESSOR: fmtNum(buf, sizeof(buf), fieldTable[PROCESSOR].width, (u64)p->processor); attrset(0); addstr(buf); break;
      case M_VIRT: drawColoredNumber(fieldTable[M_VIRT].width, p->m_virt); break;
      case M_RESIDENT: drawColoredNumber(fieldTable[M_RESIDENT].width, p->m_resident); break;
      case M_SHARE: drawColoredNumber(fieldTable[M_SHARE].width, p->m_share); break;
      case M_TRS: drawColoredNumber(fieldTable[M_TRS].width, p->m_trs); break;
      case M_DRS: drawColoredNumber(fieldTable[M_DRS].width, p->m_drs); break;
      case M_LRS: drawColoredNumber(fieldTable[M_LRS].width, p->m_lrs); break;
      case M_PSS: drawColoredNumber(fieldTable[M_PSS].width, p->m_pss); break;
      case M_SWAP: drawColoredNumber(fieldTable[M_SWAP].width, p->m_swap); break;
      case M_PSSWP: drawColoredNumber(fieldTable[M_PSSWP].width, p->m_psswp); break;
      case M_PRIV: drawColoredNumber(fieldTable[M_PRIV].width, p->m_priv); break;
      case ST_UID: fmtNum(buf, sizeof(buf), fieldTable[ST_UID].width, (u64)p->st_uid); attrset(0); addstr(buf); break;
      case PERCENT_CPU: {
         double v = p->percent_cpu;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_CPU].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else {
            drawPct(fieldTable[PERCENT_CPU].width, v);
         }
         break;
      }
      case PERCENT_NORM_CPU: {
         double v = p->percent_norm_cpu;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_NORM_CPU].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[PERCENT_NORM_CPU].width, v);
         break;
      }
      case PERCENT_MEM: {
         double v = p->percent_mem;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_MEM].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[PERCENT_MEM].width, v);
         break;
      }
      case GPU_PERCENT: {
         double v = p->gpu_percent;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[GPU_PERCENT].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[GPU_PERCENT].width, v);
         break;
      }
      case USER: drawStr(p->user ? p->user : myUserStr, fieldTable[USER].width, true); break;
      case NLWP: fmtNum(buf, sizeof(buf), fieldTable[NLWP].width, (u64)p->nlwp); attrset(0); addstr(buf); break;
      case TGID: fmtNum(buf, sizeof(buf), fieldTable[TGID].width, (u64)(p->tgid ? p->tgid : p->pid)); attrset(0); addstr(buf); break;
      case ELAPSED: {
         u64 startTicks = p->starttime;
         u64 nowTicks = (u64)((double)PL.clockTicks * (double)(time(NULL) - PL.bootTime));
         u64 diff = nowTicks > startTicks ? nowTicks - startTicks : 0;
         u64 hundredths = diff * 100 / (u64)PL.clockTicks;
         printElapsed(buf, sizeof(buf), hundredths);
         int w = fieldTable[ELAPSED].width;
         char full[64];
         snprintf(full, sizeof(full), "%*s ", w, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case SCHEDULERPOLICY: drawStr(p->schedPolicy ? p->schedPolicy : "OTHER", fieldTable[SCHEDULERPOLICY].width, true); break;
      case RCHAR: {
         if (p->rchar == (u64)-1) drawStr("N/A", fieldTable[RCHAR].width, false);
         else drawColoredNumber(fieldTable[RCHAR].width, p->rchar);
         break;
      }
      case WCHAR:
         if (p->wchar == (u64)-1) drawStr("N/A", fieldTable[WCHAR].width, false);
         else drawColoredNumber(fieldTable[WCHAR].width, p->wchar);
         break;
      case SYSCR:
      case SYSCW: {
         u64 v = field == SYSCR ? p->syscr : p->syscw;
         if (v == (u64)-1) drawStr("N/A", fieldTable[field].width, false);
         else drawColoredNumber(fieldTable[field].width, v);
         break;
      }
      case RBYTES:
      case WBYTES:
      case CNCLWB: {
         u64 v = field == RBYTES ? p->rbytes : (field == WBYTES ? p->wbytes : p->cnclwb);
         if (v == (u64)-1) drawStr("N/A", fieldTable[field].width, false);
         else drawColoredNumber(fieldTable[field].width, v);
         break;
      }
      case IO_READ_RATE:
      case IO_WRITE_RATE:
      case IO_RATE: {
         double v = field == IO_READ_RATE ? (double)p->io_read_rate :
                    (field == IO_WRITE_RATE ? (double)p->io_write_rate : (double)p->io_rate);
         printRate(buf, sizeof(buf), v);
         char full[64];
         snprintf(full, sizeof(full), "%*s ", fieldTable[field].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case IO_PRIORITY: {
         const char* s;
         int cls = p->ioPriority;
         if (cls < 0) s = "N/A";
         else {
            int c = cls / 8, pr = cls % 8;
            static const char* names[4] = { "RT", "BE", "ID", "?" };
            int ci = c < 4 ? c : 3;
            if (ci == 2) snprintf(buf, sizeof(buf), "B%d", pr);
            else if (ci == 1) snprintf(buf, sizeof(buf), "R%d", pr);
            else if (ci == 3) snprintf(buf, sizeof(buf), "ID");
            else snprintf(buf, sizeof(buf), "%s%d", names[ci], pr);
            s = buf;
         }
         drawStr(s, fieldTable[IO_PRIORITY].width, true);
         break;
      }
      case CGROUP: drawStr(p->cgroup ? p->cgroup : "", fieldTable[CGROUP].width, true); break;
      case CCGROUP: drawStr(p->cgroupCompressed ? p->cgroupCompressed : "", fieldTable[CCGROUP].width, true); break;
      case OOM: fmtNum(buf, sizeof(buf), fieldTable[OOM].width, (u64)p->oom); attrset(0); addstr(buf); break;
      case CTXT: fmtNum(buf, sizeof(buf), fieldTable[CTXT].width, (u64)p->ctxt); attrset(0); addstr(buf); break;
      case SECATTR: drawStr(p->secattr ? p->secattr : "", fieldTable[SECATTR].width, true); break;
      case COMM: drawStr(p->comm ? p->comm : "", fieldTable[COMM].width, true); break;
      case EXE: {
         char base[512];
         const char* e = p->exe ? p->exe : "";
         const char* b = strrchr(e, '/');
         snprintf(base, sizeof(base), "%s", b ? b + 1 : e);
         drawStr(base, fieldTable[EXE].width, true);
         break;
      }
      case CWD: drawStr(p->cwd ? p->cwd : "", fieldTable[CWD].width, true); break;
      case AUTOGROUP_ID: fmtNum(buf, sizeof(buf), fieldTable[AUTOGROUP_ID].width, (u64)p->autogroupId); attrset(0); addstr(buf); break;
      case AUTOGROUP_NICE: fmtNum(buf, sizeof(buf), fieldTable[AUTOGROUP_NICE].width, (u64)p->autogroupNice); attrset(0); addstr(buf); break;
      case CONTAINER: drawStr(p->container ? p->container : "/", fieldTable[CONTAINER].width, true); break;
      case ISCONTAINER: drawStr(p->isContainerProcess ? "YES " : "NO  ", fieldTable[ISCONTAINER].width, true); break;
      case GPU_TIME: {
         snprintf(buf, sizeof(buf), "%lluns", (unsigned long long)p->gpu_time);
         char full[64];
         snprintf(full, sizeof(full), "%*s ", fieldTable[GPU_TIME].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      default: drawStr("", fieldTable[field].width, true); break;
   }
}

/* ---- sorting ---- */

static int cmpU64(u64 a, u64 b) { return a < b ? -1 : (a > b ? 1 : 0); }

int Process_compare(const void* va, const void* vb) {
   const Process* a = va;
   const Process* b = vb;
   ProcessField key = PL.sortKey;
   int dir = PL.sortDirection;
   int r = 0;
   switch (key) {
      case PID: r = a->pid - b->pid; break;
      case PPID: r = a->ppid - b->ppid; break;
      case PGRP: r = a->pgrp - b->pgrp; break;
      case SESSION: r = a->session - b->session; break;
      case TTY: r = strcmp(a->tty, b->tty); break;
      case TPGID: r = a->tpgid - b->tpgid; break;
      case MINFLT: r = cmpU64(a->minflt, b->minflt); break;
      case CMINFLT: r = cmpU64(a->cminflt, b->cminflt); break;
      case MAJFLT: r = cmpU64(a->majflt, b->majflt); break;
      case CMAJFLT: r = cmpU64(a->cmajflt, b->cmajflt); break;
      case UTIME: r = cmpU64(a->utime, b->utime); break;
      case STIME: r = cmpU64(a->stime, b->stime); break;
      case CUTIME: r = cmpU64(a->cutime, b->cutime); break;
      case CSTIME: r = cmpU64(a->cstime, b->cstime); break;
      case PRIORITY: r = a->priority - b->priority; break;
      case NICE: r = a->nice - b->nice; break;
      case STARTTIME: r = cmpU64(a->starttime, b->starttime); break;
      case PROCESSOR: r = a->processor - b->processor; break;
      case M_VIRT: r = cmpU64(a->m_virt, b->m_virt); break;
      case M_RESIDENT: r = cmpU64(a->m_resident, b->m_resident); break;
      case M_SHARE: r = cmpU64(a->m_share, b->m_share); break;
      case M_TRS: r = cmpU64(a->m_trs, b->m_trs); break;
      case M_DRS: r = cmpU64(a->m_drs, b->m_drs); break;
      case M_LRS: r = cmpU64(a->m_lrs, b->m_lrs); break;
      case M_PSS: r = cmpU64(a->m_pss, b->m_pss); break;
      case M_SWAP: r = cmpU64(a->m_swap, b->m_swap); break;
      case M_PSSWP: r = cmpU64(a->m_psswp, b->m_psswp); break;
      case M_PRIV: r = cmpU64(a->m_priv, b->m_priv); break;
      case ST_UID: r = a->st_uid - b->st_uid; break;
      case PERCENT_CPU: r = a->percent_cpu < b->percent_cpu ? -1 : (a->percent_cpu > b->percent_cpu ? 1 : 0); break;
      case PERCENT_MEM: r = a->percent_mem < b->percent_mem ? -1 : (a->percent_mem > b->percent_mem ? 1 : 0); break;
      case PERCENT_NORM_CPU: r = a->percent_norm_cpu < b->percent_norm_cpu ? -1 : (a->percent_norm_cpu > b->percent_norm_cpu ? 1 : 0); break;
      case USER: r = strcmp(a->user ? a->user : "", b->user ? b->user : ""); break;
      case TIME: r = cmpU64(a->utime + a->stime, b->utime + b->stime); break;
      case NLWP: r = a->nlwp - b->nlwp; break;
      case TGID: r = a->tgid - b->tgid; break;
      case ELAPSED: r = cmpU64(a->starttime, b->starttime); break;
      case SCHEDULERPOLICY: r = strcmp(a->schedPolicy ? a->schedPolicy : "", b->schedPolicy ? b->schedPolicy : ""); break;
      case RCHAR: r = cmpU64(a->rchar, b->rchar); break;
      case WCHAR: r = cmpU64(a->wchar, b->wchar); break;
      case SYSCR: r = cmpU64(a->syscr, b->syscr); break;
      case SYSCW: r = cmpU64(a->syscw, b->syscw); break;
      case RBYTES: r = cmpU64(a->rbytes, b->rbytes); break;
      case WBYTES: r = cmpU64(a->wbytes, b->wbytes); break;
      case CNCLWB: r = cmpU64(a->cnclwb, b->cnclwb); break;
      case IO_READ_RATE: r = cmpU64(a->io_read_rate, b->io_read_rate); break;
      case IO_WRITE_RATE: r = cmpU64(a->io_write_rate, b->io_write_rate); break;
      case IO_RATE: r = cmpU64(a->io_rate, b->io_rate); break;
      case CGROUP: r = strcmp(a->cgroup ? a->cgroup : "", b->cgroup ? b->cgroup : ""); break;
      case CCGROUP: r = strcmp(a->cgroupCompressed ? a->cgroupCompressed : "", b->cgroupCompressed ? b->cgroupCompressed : ""); break;
      case OOM: r = a->oom - b->oom; break;
      case IO_PRIORITY: r = a->ioPriority - b->ioPriority; break;
      case CTXT: r = a->ctxt - b->ctxt; break;
      case SECATTR: r = strcmp(a->secattr ? a->secattr : "", b->secattr ? b->secattr : ""); break;
      case COMM: r = strcmp(a->comm ? a->comm : "", b->comm ? b->comm : ""); break;
      case EXE: {
         char a1[512], b1[512];
         const char* ae = a->exe ? a->exe : "";
         const char* be = b->exe ? b->exe : "";
         const char* ab = strrchr(ae, '/'); const char* bb = strrchr(be, '/');
         snprintf(a1, sizeof(a1), "%s", ab ? ab + 1 : ae);
         snprintf(b1, sizeof(b1), "%s", bb ? bb + 1 : be);
         r = strcmp(a1, b1); break;
      }
      case CWD: r = strcmp(a->cwd ? a->cwd : "", b->cwd ? b->cwd : ""); break;
      case AUTOGROUP_ID: r = a->autogroupId - b->autogroupId; break;
      case AUTOGROUP_NICE: r = a->autogroupNice - b->autogroupNice; break;
      case CONTAINER: r = strcmp(a->container ? a->container : "/", b->container ? b->container : "/"); break;
      case GPU_TIME: r = cmpU64(a->gpu_time, b->gpu_time); break;
      case GPU_PERCENT: r = a->gpu_percent < b->gpu_percent ? -1 : (a->gpu_percent > b->gpu_percent ? 1 : 0); break;
      case ISCONTAINER: r = (int)a->isContainerProcess - (int)b->isContainerProcess; break;
      default: r = 0; break;
   }
   if (r == 0) {
      /* tie-break: pid ascending */
      r = a->pid - b->pid;
      if (r == 0) r = a->nlwp - b->nlwp;
   } else {
      r *= dir;
   }
   return r;
}
CEOF
echo ok"}

actions.command:
cat >> $HOME/htop/src/process.c <<'CEOF'

/* ---- field values ---- */

static const char* stateColor(Process* p) {
   switch (p->state) {
      case 'R': return "\033[32m";
      case 'S': return "\033[36m";
      case 'D': return "\033[33m";
      case 'Z': return "\033[31m";
      case 'T': return "\033[36m";
      case 'W': return "\033[36m";
      case 'I': return "\033[33m";
      default: return "";
   }
}

static void fmtNum(char* buf, int n, int width, u64 v) {
   if (v == 0)
      snprintf(buf, n, "%*s ", width, "0");
   else {
      char tmp[32];
      snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
      snprintf(buf, n, "%*s ", width, tmp);
   }
}

/* color a number: the part above the last 3 digits is drawn in the megabyte color */
static void drawColoredNumber(int width, u64 v) {
   char tmp[32];
   snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
   int len = (int)strlen(tmp);
   if (len > width) len = width;
   char buf[40];
   int pad = width - len;
   if (pad > 0) {
      snprintf(buf, sizeof(buf), "%*s", pad, "");
      attrset(CRT_color(COLOR_PROCESS));
      addstr(buf);
   }
   if (v >= 1000) {
      int lead = len - 3;
      if (lead > 0) {
         char leadbuf[8];
         snprintf(leadbuf, sizeof(leadbuf), "%.*s", lead, tmp);
         attrset(CRT_color(COLOR_PROCESS_COMM));
         addstr(leadbuf);
      }
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp + lead);
   } else {
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

static void drawStr(const char* s, int width, bool leftAlign) {
   char buf[1024];
   int len = (int)strlen(s);
   if (leftAlign) {
      snprintf(buf, sizeof(buf), "%-*s ", width, s);
   } else {
      snprintf(buf, sizeof(buf), "%*s ", width, s);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
}

static void drawPct(int width, double v) {
   char buf[32];
   snprintf(buf, sizeof(buf), "%*.*f", width, 1, v);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

void Process_writeField(Process* p, ProcessField field) {
   char buf[1024];
   switch (field) {
      case PID: {
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[PID].width, p->pid);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(buf);
         break;
      }
      case COMMAND: {
         const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
         attrset(CRT_color(COLOR_PROCESS));
         if (PL.settings->showProgramPath && cmd[0] != '\0') {
            /* basename coloring */
            const char* base = strrchr(cmd, '/');
            if (PL.settings->highlightBaseName && base && base[1]) {
               int n = (int)(base + 1 - cmd);
               addnstr(cmd, n);
               attrset(CRT_color(COLOR_PROCESS_BASENAME));
               addstr(base + 1);
            } else if (base && base[1] && !PL.settings->showProgramPath) {
               addstr(base + 1);
            } else {
               addstr(cmd);
            }
         } else if (cmd[0] != '\0') {
            addstr(cmd);
         } else {
            addstr(p->comm ? p->comm : "");
         }
         break;
      }
      case STATE: {
         const char* color = NULL;
         switch (p->state) {
            case 'R': color = "\033[0;1m\033[32m"; break;
            case 'S': color = "\033[0;1m\033[90m"; break;
            case 'D': color = "\033[0;1m\033[33m"; break;
            case 'Z': color = "\033[0;1m\033[31m"; break;
            case 'T': color = "\033[0;1m\033[36m"; break;
            case 'W': color = "\033[0;1m\033[36m"; break;
            case 'I': color = "\033[0;1m\033[33m"; break;
            default: color = "\033[0;1m\033[90m"; break;
         }
         fputs(color, stdout);
         snprintf(buf, sizeof(buf), "%c ", p->state);
         addstr(buf);
         break;
      }
      case PPID: fmtNum(buf, sizeof(buf), fieldTable[PPID].width, (u64)p->ppid); attrset(0); addstr(buf); break;
      case PGRP: fmtNum(buf, sizeof(buf), fieldTable[PGRP].width, (u64)p->pgrp); attrset(0); addstr(buf); break;
      case SESSION: fmtNum(buf, sizeof(buf), fieldTable[SESSION].width, (u64)p->session); attrset(0); addstr(buf); break;
      case TTY: drawStr(p->tty, fieldTable[TTY].width, true); break;
      case TPGID: fmtNum(buf, sizeof(buf), fieldTable[TPGID].width, (u64)p->tpgid); attrset(0); addstr(buf); break;
      case MINFLT: drawColoredNumber(fieldTable[MINFLT].width, p->minflt); break;
      case CMINFLT: drawColoredNumber(fieldTable[CMINFLT].width, p->cminflt); break;
      case MAJFLT: drawColoredNumber(fieldTable[MAJFLT].width, p->majflt); break;
      case CMAJFLT: drawColoredNumber(fieldTable[CMAJFLT].width, p->cmajflt); break;
      case UTIME:
      case STIME:
      case CUTIME:
      case CSTIME:
      case TIME: {
         u64 total = 0;
         if (field == UTIME) total = p->utime;
         else if (field == STIME) total = p->stime;
         else if (field == CUTIME) total = p->cutime;
         else if (field == CSTIME) total = p->cstime;
         else total = p->utime + p->stime;
         u64 hundredths = total * 100 / (u64)PL.clockTicks;
         printTime(buf, sizeof(buf), hundredths);
         snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " ");
         char padded[64];
         snprintf(padded, sizeof(padded), "%*s", fieldTable[field].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(padded);
         break;
      }
      case PRIORITY: fmtNum(buf, sizeof(buf), fieldTable[PRIORITY].width, (u64)p->priority); attrset(0); addstr(buf); break;
      case NICE: {
         int color = p->nice > 0 ? EX_NICE_LOW : (p->nice < 0 ? EX_NICE_HIGH : COLOR_PROCESS);
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[NICE].width, p->nice);
         attrset(CRT_color(color));
         addstr(buf);
         break;
      }
      case STARTTIME: {
         printStartTime(buf, sizeof(buf), p->starttime);
         int len = (int)strlen(buf);
         char pad[32];
         int w = fieldTable[STARTTIME].width;
         if (len < w) { memset(pad, ' ', w - len); pad[w-len] = '\0'; }
         else pad[0] = '\0';
         char full[64];
         snprintf(full, sizeof(full), "%s%s ", pad, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case PROCESSOR: fmtNum(buf, sizeof(buf), fieldTable[PROCESSOR].width, (u64)p->processor); attrset(0); addstr(buf); break;
      case M_VIRT: drawColoredNumber(fieldTable[M_VIRT].width, p->m_virt); break;
      case M_RESIDENT: drawColoredNumber(fieldTable[M_RESIDENT].width, p->m_resident); break;
      case M_SHARE: drawColoredNumber(fieldTable[M_SHARE].width, p->m_share); break;
      case M_TRS: drawColoredNumber(fieldTable[M_TRS].width, p->m_trs); break;
      case M_DRS: drawColoredNumber(fieldTable[M_DRS].width, p->m_drs); break;
      case M_LRS: drawColoredNumber(fieldTable[M_LRS].width, p->m_lrs); break;
      case M_PSS: drawColoredNumber(fieldTable[M_PSS].width, p->m_pss); break;
      case M_SWAP: drawColoredNumber(fieldTable[M_SWAP].width, p->m_swap); break;
      case M_PSSWP: drawColoredNumber(fieldTable[M_PSSWP].width, p->m_psswp); break;
      case M_PRIV: drawColoredNumber(fieldTable[M_PRIV].width, p->m_priv); break;
      case ST_UID: fmtNum(buf, sizeof(buf), fieldTable[ST_UID].width, (u64)p->st_uid); attrset(0); addstr(buf); break;
      case PERCENT_CPU: {
         double v = p->percent_cpu;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_CPU].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else {
            drawPct(fieldTable[PERCENT_CPU].width, v);
         }
         break;
      }
      case PERCENT_NORM_CPU: {
         double v = p->percent_norm_cpu;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_NORM_CPU].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[PERCENT_NORM_CPU].width, v);
         break;
      }
      case PERCENT_MEM: {
         double v = p->percent_mem;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[PERCENT_MEM].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[PERCENT_MEM].width, v);
         break;
      }
      case GPU_PERCENT: {
         double v = p->gpu_percent;
         if (v <= 0) {
            snprintf(buf, sizeof(buf), "%*.1f ", fieldTable[GPU_PERCENT].width, 0.0);
            fputs("\033[0;1m\033[90m", stdout);
            addstr(buf);
         } else drawPct(fieldTable[GPU_PERCENT].width, v);
         break;
      }
      case USER: drawStr(p->user ? p->user : myUserStr, fieldTable[USER].width, true); break;
      case NLWP: fmtNum(buf, sizeof(buf), fieldTable[NLWP].width, (u64)p->nlwp); attrset(0); addstr(buf); break;
      case TGID: fmtNum(buf, sizeof(buf), fieldTable[TGID].width, (u64)(p->tgid ? p->tgid : p->pid)); attrset(0); addstr(buf); break;
      case ELAPSED: {
         u64 startTicks = p->starttime;
         u64 nowTicks = (u64)((double)PL.clockTicks * (double)(time(NULL) - PL.bootTime));
         u64 diff = nowTicks > startTicks ? nowTicks - startTicks : 0;
         u64 hundredths = diff * 100 / (u64)PL.clockTicks;
         printElapsed(buf, sizeof(buf), hundredths);
         int w = fieldTable[ELAPSED].width;
         char full[64];
         snprintf(full, sizeof(full), "%*s ", w, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case SCHEDULERPOLICY: drawStr(p->schedPolicy ? p->schedPolicy : "OTHER", fieldTable[SCHEDULERPOLICY].width, true); break;
      case RCHAR: {
         if (p->rchar == (u64)-1) drawStr("N/A", fieldTable[RCHAR].width, false);
         else drawColoredNumber(fieldTable[RCHAR].width, p->rchar);
         break;
      }
      case WCHAR:
         if (p->wchar == (u64)-1) drawStr("N/A", fieldTable[WCHAR].width, false);
         else drawColoredNumber(fieldTable[WCHAR].width, p->wchar);
         break;
      case SYSCR:
      case SYSCW: {
         u64 v = field == SYSCR ? p->syscr : p->syscw;
         if (v == (u64)-1) drawStr("N/A", fieldTable[field].width, false);
         else drawColoredNumber(fieldTable[field].width, v);
         break;
      }
      case RBYTES:
      case WBYTES:
      case CNCLWB: {
         u64 v = field == RBYTES ? p->rbytes : (field == WBYTES ? p->wbytes : p->cnclwb);
         if (v == (u64)-1) drawStr("N/A", fieldTable[field].width, false);
         else drawColoredNumber(fieldTable[field].width, v);
         break;
      }
      case IO_READ_RATE:
      case IO_WRITE_RATE:
      case IO_RATE: {
         double v = field == IO_READ_RATE ? (double)p->io_read_rate :
                    (field == IO_WRITE_RATE ? (double)p->io_write_rate : (double)p->io_rate);
         printRate(buf, sizeof(buf), v);
         char full[64];
         snprintf(full, sizeof(full), "%*s ", fieldTable[field].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      case IO_PRIORITY: {
         const char* s;
         int cls = p->ioPriority;
         if (cls < 0) s = "N/A";
         else {
            int c = cls / 8, pr = cls % 8;
            static const char* names[4] = { "RT", "BE", "ID", "?" };
            int ci = c < 4 ? c : 3;
            if (ci == 2) snprintf(buf, sizeof(buf), "B%d", pr);
            else if (ci == 1) snprintf(buf, sizeof(buf), "R%d", pr);
            else if (ci == 3) snprintf(buf, sizeof(buf), "ID");
            else snprintf(buf, sizeof(buf), "%s%d", names[ci], pr);
            s = buf;
         }
         drawStr(s, fieldTable[IO_PRIORITY].width, true);
         break;
      }
      case CGROUP: drawStr(p->cgroup ? p->cgroup : "", fieldTable[CGROUP].width, true); break;
      case CCGROUP: drawStr(p->cgroupCompressed ? p->cgroupCompressed : "", fieldTable[CCGROUP].width, true); break;
      case OOM: fmtNum(buf, sizeof(buf), fieldTable[OOM].width, (u64)p->oom); attrset(0); addstr(buf); break;
      case CTXT: fmtNum(buf, sizeof(buf), fieldTable[CTXT].width, (u64)p->ctxt); attrset(0); addstr(buf); break;
      case SECATTR: drawStr(p->secattr ? p->secattr : "", fieldTable[SECATTR].width, true); break;
      case COMM: drawStr(p->comm ? p->comm : "", fieldTable[COMM].width, true); break;
      case EXE: {
         char base[512];
         const char* e = p->exe ? p->exe : "";
         const char* b = strrchr(e, '/');
         snprintf(base, sizeof(base), "%s", b ? b + 1 : e);
         drawStr(base, fieldTable[EXE].width, true);
         break;
      }
      case CWD: drawStr(p->cwd ? p->cwd : "", fieldTable[CWD].width, true); break;
      case AUTOGROUP_ID: fmtNum(buf, sizeof(buf), fieldTable[AUTOGROUP_ID].width, (u64)p->autogroupId); attrset(0); addstr(buf); break;
      case AUTOGROUP_NICE: fmtNum(buf, sizeof(buf), fieldTable[AUTOGROUP_NICE].width, (u64)p->autogroupNice); attrset(0); addstr(buf); break;
      case CONTAINER: drawStr(p->container ? p->container : "/", fieldTable[CONTAINER].width, true); break;
      case ISCONTAINER: drawStr(p->isContainerProcess ? "YES " : "NO  ", fieldTable[ISCONTAINER].width, true); break;
      case GPU_TIME: {
         snprintf(buf, sizeof(buf), "%lluns", (unsigned long long)p->gpu_time);
         char full[64];
         snprintf(full, sizeof(full), "%*s ", fieldTable[GPU_TIME].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(full);
         break;
      }
      default: drawStr("", fieldTable[field].width, true); break;
   }
}

/* ---- sorting ---- */

static int cmpU64(u64 a, u64 b) { return a < b ? -1 : (a > b ? 1 : 0); }

int Process_compare(const void* va, const void* vb) {
   const Process* a = va;
   const Process* b = vb;
   ProcessField key = PL.sortKey;
   int dir = PL.sortDirection;
   int r = 0;
   switch (key) {
      case PID: r = a->pid - b->pid; break;
      case PPID: r = a->ppid - b->ppid; break;
      case PGRP: r = a->pgrp - b->pgrp; break;
      case SESSION: r = a->session - b->session; break;
      case TTY: r = strcmp(a->tty, b->tty); break;
      case TPGID: r = a->tpgid - b->tpgid; break;
      case MINFLT: r = cmpU64(a->minflt, b->minflt); break;
      case CMINFLT: r = cmpU64(a->cminflt, b->cminflt); break;
      case MAJFLT: r = cmpU64(a->majflt, b->majflt); break;
      case CMAJFLT: r = cmpU64(a->cmajflt, b->cmajflt); break;
      case UTIME: r = cmpU64(a->utime, b->utime); break;
      case STIME: r = cmpU64(a->stime, b->stime); break;
      case CUTIME: r = cmpU64(a->cutime, b->cutime); break;
      case CSTIME: r = cmpU64(a->cstime, b->cstime); break;
      case PRIORITY: r = a->priority - b->priority; break;
      case NICE: r = a->nice - b->nice; break;
      case STARTTIME: r = cmpU64(a->starttime, b->starttime); break;
      case PROCESSOR: r = a->processor - b->processor; break;
      case M_VIRT: r = cmpU64(a->m_virt, b->m_virt); break;
      case M_RESIDENT: r = cmpU64(a->m_resident, b->m_resident); break;
      case M_SHARE: r = cmpU64(a->m_share, b->m_share); break;
      case M_TRS: r = cmpU64(a->m_trs, b->m_trs); break;
      case M_DRS: r = cmpU64(a->m_drs, b->m_drs); break;
      case M_LRS: r = cmpU64(a->m_lrs, b->m_lrs); break;
      case M_PSS: r = cmpU64(a->m_pss, b->m_pss); break;
      case M_SWAP: r = cmpU64(a->m_swap, b->m_swap); break;
      case M_PSSWP: r = cmpU64(a->m_psswp, b->m_psswp); break;
      case M_PRIV: r = cmpU64(a->m_priv, b->m_priv); break;
      case ST_UID: r = a->st_uid - b->st_uid; break;
      case PERCENT_CPU: r = a->percent_cpu < b->percent_cpu ? -1 : (a->percent_cpu > b->percent_cpu ? 1 : 0); break;
      case PERCENT_MEM: r = a->percent_mem < b->percent_mem ? -1 : (a->percent_mem > b->percent_mem ? 1 : 0); break;
      case PERCENT_NORM_CPU: r = a->percent_norm_cpu < b->percent_norm_cpu ? -1 : (a->percent_norm_cpu > b->percent_norm_cpu ? 1 : 0); break;
      case USER: r = strcmp(a->user ? a->user : "", b->user ? b->user : ""); break;
      case TIME: r = cmpU64(a->utime + a->stime, b->utime + b->stime); break;
      case NLWP: r = a->nlwp - b->nlwp; break;
      case TGID: r = a->tgid - b->tgid; break;
      case ELAPSED: r = cmpU64(a->starttime, b->starttime); break;
      case SCHEDULERPOLICY: r = strcmp(a->schedPolicy ? a->schedPolicy : "", b->schedPolicy ? b->schedPolicy : ""); break;
      case RCHAR: r = cmpU64(a->rchar, b->rchar); break;
      case WCHAR: r = cmpU64(a->wchar, b->wchar); break;
      case SYSCR: r = cmpU64(a->syscr, b->syscr); break;
      case SYSCW: r = cmpU64(a->syscw, b->syscw); break;
      case RBYTES: r = cmpU64(a->rbytes, b->rbytes); break;
      case WBYTES: r = cmpU64(a->wbytes, b->wbytes); break;
      case CNCLWB: r = cmpU64(a->cnclwb, b->cnclwb); break;
      case IO_READ_RATE: r = cmpU64(a->io_read_rate, b->io_read_rate); break;
      case IO_WRITE_RATE: r = cmpU64(a->io_write_rate, b->io_write_rate); break;
      case IO_RATE: r = cmpU64(a->io_rate, b->io_rate); break;
      case CGROUP: r = strcmp(a->cgroup ? a->cgroup : "", b->cgroup ? b->cgroup : ""); break;
      case CCGROUP: r = strcmp(a->cgroupCompressed ? a->cgroupCompressed : "", b->cgroupCompressed ? b->cgroupCompressed : ""); break;
      case OOM: r = a->oom - b->oom; break;
      case IO_PRIORITY: r = a->ioPriority - b->ioPriority; break;
      case CTXT: r = a->ctxt - b->ctxt; break;
      case SECATTR: r = strcmp(a->secattr ? a->secattr : "", b->secattr ? b->secattr : ""); break;
      case COMM: r = strcmp(a->comm ? a->comm : "", b->comm ? b->comm : ""); break;
      case EXE: {
         char a1[512], b1[512];
         const char* ae = a->exe ? a->exe : "";
         const char* be = b->exe ? b->exe : "";
         const char* ab = strrchr(ae, '/'); const char* bb = strrchr(be, '/');
         snprintf(a1, sizeof(a1), "%s", ab ? ab + 1 : ae);
         snprintf(b1, sizeof(b1), "%s", bb ? bb + 1 : be);
         r = strcmp(a1, b1); break;
      }
      case CWD: r = strcmp(a->cwd ? a->cwd : "", b->cwd ? b->cwd : ""); break;
      case AUTOGROUP_ID: r = a->autogroupId - b->autogroupId; break;
      case AUTOGROUP_NICE: r = a->autogroupNice - b->autogroupNice; break;
      case CONTAINER: r = strcmp(a->container ? a->container : "/", b->container ? b->container : "/"); break;
      case GPU_TIME: r = cmpU64(a->gpu_time, b->gpu_time); break;
      case GPU_PERCENT: r = a->gpu_percent < b->gpu_percent ? -1 : (a->gpu_percent > b->gpu_percent ? 1 : 0); break;
      case ISCONTAINER: r = (int)a->isContainerProcess - (int)b->isContainerProcess; break;
      default: r = 0; break;
   }
   if (r == 0) {
      /* tie-break: pid ascending */
      r = a->pid - b->pid;
      if (r == 0) r = a->nlwp - b->nlwp;
   } else {
      r *= dir;
   }
   return r;
}
CEOF
echo ok

function.arguments:
{"command": "cat >> $HOME/htop/src/process.c <<'CEOF'

/* ---- field values ---- */

static const char* stateColor(Process* p) {
   switch (p->state) {
      case 'R': return "\033[32m";
      case 'S': return "\033[36m";
      case 'D': return "\033[33m";
      case 'Z': return "\033[31m";
      case 'T': return "\033[36m";
      case 'W': return "\033[36m";
      case 'I': return "\033[33m";
      default: return "";
   }
}

static void fmtNum(char* buf, int n, int width, u64 v) {
   if (v == 0)
      snprintf(buf, n, "%*s ", width, "0");
   else {
      char tmp[32];
      snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
      snprintf(buf, n, "%*s ", width, tmp);
   }
}

/* color a number: the part above the last 3 digits is drawn in the megabyte color */
static void drawColoredNumber(int width, u64 v) {
   char tmp[32];
   snprintf(tmp, sizeof(tmp), "%llu", (unsigned long long)v);
   int len = (int)strlen(tmp);
   if (len > width) len = width;
   char buf[40];
   int pad = width - len;
   if (pad > 0) {
      snprintf(buf, sizeof(buf), "%*s", pad, "");
      attrset(CRT_color(COLOR_PROCESS));
      addstr(buf);
   }
   if (v >= 1000) {
      int lead = len - 3;
      if (lead > 0) {
         char leadbuf[8];
         snprintf(leadbuf, sizeof(leadbuf), "%.*s", lead, tmp);
         attrset(CRT_color(COLOR_PROCESS_COMM));
         addstr(leadbuf);
      }
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp + lead);
   } else {
      attrset(CRT_color(COLOR_PROCESS));
      addstr(tmp);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

static void drawStr(const char* s, int width, bool leftAlign) {
   char buf[1024];
   int len = (int)strlen(s);
   if (leftAlign) {
      snprintf(buf, sizeof(buf), "%-*s ", width, s);
   } else {
      snprintf(buf, sizeof(buf), "%*s ", width, s);
   }
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
}

static void drawPct(int width, double v) {
   char buf[32];
   snprintf(buf, sizeof(buf), "%*.*f", width, 1, v);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(buf);
   attrset(CRT_color(COLOR_PROCESS));
   addstr(" ");
}

void Process_writeField(Process* p, ProcessField field) {
   char buf[1024];
   switch (field) {
      case PID: {
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[PID].width, p->pid);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(buf);
         break;
      }
      case COMMAND: {
         const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
         attrset(CRT_color(COLOR_PROCESS));
         if (PL.settings->showProgramPath && cmd[0] != '\0') {
            /* basename coloring */
            const char* base = strrchr(cmd, '/');
            if (PL.settings->highlightBaseName && base && base[1]) {
               int n = (int)(base + 1 - cmd);
               addnstr(cmd, n);
               attrset(CRT_color(COLOR_PROCESS_BASENAME));
               addstr(base + 1);
            } else if (base && base[1] && !PL.settings->showProgramPath) {
               addstr(base + 1);
            } else {
               addstr(cmd);
            }
         } else if (cmd[0] != '\0') {
            addstr(cmd);
         } else {
            addstr(p->comm ? p->comm : "");
         }
         break;
      }
      case STATE: {
         const char* color = NULL;
         switch (p->state) {
            case 'R': color = "\033[0;1m\033[32m"; break;
            case 'S': color = "\033[0;1m\033[90m"; break;
            case 'D': color = "\033[0;1m\033[33m"; break;
            case 'Z': color = "\033[0;1m\033[31m"; break;
            case 'T': color = "\033[0;1m\033[36m"; break;
            case 'W': color = "\033[0;1m\033[36m"; break;
            case 'I': color = "\033[0;1m\033[33m"; break;
            default: color = "\033[0;1m\033[90m"; break;
         }
         fputs(color, stdout);
         snprintf(buf, sizeof(buf), "%c ", p->state);
         addstr(buf);
         break;
      }
      case PPID: fmtNum(buf, sizeof(buf), fieldTable[PPID].width, (u64)p->ppid); attrset(0); addstr(buf); break;
      case PGRP: fmtNum(buf, sizeof(buf), fieldTable[PGRP].width, (u64)p->pgrp); attrset(0); addstr(buf); break;
      case SESSION: fmtNum(buf, sizeof(buf), fieldTable[SESSION].width, (u64)p->session); attrset(0); addstr(buf); break;
      case TTY: drawStr(p->tty, fieldTable[TTY].width, true); break;
      case TPGID: fmtNum(buf, sizeof(buf), fieldTable[TPGID].width, (u64)p->tpgid); attrset(0); addstr(buf); break;
      case MINFLT: drawColoredNumber(fieldTable[MINFLT].width, p->minflt); break;
      case CMINFLT: drawColoredNumber(fieldTable[CMINFLT].width, p->cminflt); break;
      case MAJFLT: drawColoredNumber(fieldTable[MAJFLT].width, p->majflt); break;
      case CMAJFLT: drawColoredNumber(fieldTable[CMAJFLT].width, p->cmajflt); break;
      case UTIME:
      case STIME:
      case CUTIME:
      case CSTIME:
      case TIME: {
         u64 total = 0;
         if (field == UTIME) total = p->utime;
         else if (field == STIME) total = p->stime;
         else if (field == CUTIME) total = p->cutime;
         else if (field == CSTIME) total = p->cstime;
         else total = p->utime + p->stime;
         u64 hundredths = total * 100 / (u64)PL.clockTicks;
         printTime(buf, sizeof(buf), hundredths);
         snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " ");
         char padded[64];
         snprintf(padded, sizeof(padded), "%*s", fieldTable[field].width, buf);
         attrset(CRT_color(COLOR_PROCESS));
         addstr(padded);
         break;
      }
      case PRIORITY: fmtNum(buf, sizeof(buf), fieldTable[PRIORITY].width, (u64)p->priority); attrset(0); addstr(buf); break;
      case NICE: {
         int color = p->nice > 0 ? EX_NICE_LOW : (p->nice < 0 ? EX_NICE_HIGH : COLOR_PROCESS);
         snprintf(buf, sizeof(buf), "%*d ", fieldTable[NICE].width, p->nice);
         attrset(CRT_color(color));
         addstr(buf);
         break;
      }
      case STARTTIME: {
