{"command": "cat > $HOME/htop/src/meter.c <<'CEOF'
#include "htop.h"
#include <curses.h>
#include "process.c"

/* ---------------- meter ---------------- */

typedef struct Meter Meter;
struct Meter {
   int type;              /* MeterType */
   int mode;              /* MeterMode */
   char* caption;         /* caption text (displayed prefix) */
   int cpuOffset;         /* first CPU index for CPU group meters */
   int ncpu;              /* number of CPUs this meter covers */
   int ncols;             /* columns in the CPU grid */
   int height;            /* rows used */
   double values[16];
   char text[128];
   int item;
};

static Meter* Meter_new(int type, int mode, int item);
static void Meter_delete(Meter* m);
static void Meter_draw(Meter* m, int x, int y, int w);
static int Meter_height(Meter* m);

/* ---- CPU meter data ---- */

static void cpuMeterValues(Meter* m) {
   int n = m->ncpu;
   for (int i = 0; i < n && i < 16; i++) {
      int cpu = m->cpuOffset + i;
      if (cpu >= PL.cpuCount) { m->values[i] = 0; continue; }
      u64 total = PL.cpuUser[cpu] + PL.cpuSystem[cpu] + PL.cpuGuest[cpu] +
                  PL.cpuGuestNice[cpu] + PL.cpuIrq[cpu] + PL.cpuSoftIrq[cpu] +
                  PL.cpuSteal[cpu] + PL.cpuIowait[cpu] + PL.cpuNice[cpu];
      u64 prev = PL.cpuUserPrev[cpu] + PL.cpuSystemPrev[cpu] + PL.cpuGuestPrev[cpu] +
                 PL.cpuGuestNicePrev[cpu] + PL.cpuIrqPrev[cpu] + PL.cpuSoftIrqPrev[cpu] +
                 PL.cpuStealPrev[cpu] + PL.cpuIowaitPrev[cpu] + PL.cpuNicePrev[cpu];
      u64 delta = total - prev;
      u64 busy = (PL.cpuUser[cpu] - PL.cpuUserPrev[cpu]) +
                 (PL.cpuSystem[cpu] - PL.cpuSystemPrev[cpu]) +
                 (PL.cpuGuest[cpu] - PL.cpuGuestPrev[cpu]) +
                 (PL.cpuGuestNice[cpu] - PL.cpuGuestNicePrev[cpu]) +
                 (PL.cpuNice[cpu] - PL.cpuNicePrev[cpu]);
      if (!PL.settings->accountGuestInCpuMeter)
         busy -= (PL.cpuGuest[cpu] - PL.cpuGuestPrev[cpu]) + (PL.cpuGuestNice[cpu] - PL.cpuGuestNicePrev[cpu]);
      m->values[i] = delta > 0 ? (double)busy / (double)delta * 100.0 : 0.0;
   }
}

static void cpuMeterText(Meter* m, char* buf, int n) {
   /* "123: 45.6% sys:  1.2% low:  3" */
   buf[0] = '\0';
   for (int i = 0; i < m->ncpu; i++) {
      int cpu = m->cpuOffset + i;
      cpuMeterValues(m);
      char tmp[64];
      double total = m->values[i];
      double sys = 0.0, low = 0.0;
      if (cpu < PL.cpuCount) {
         u64 dTotal = (PL.cpuUser[cpu] + PL.cpuSystem[cpu] + PL.cpuGuest[cpu] + PL.cpuGuestNice[cpu] +
                       PL.cpuIrq[cpu] + PL.cpuSoftIrq[cpu] + PL.cpuSteal[cpu] + PL.cpuIowait[cpu] + PL.cpuNice[cpu])
                      - (PL.cpuUserPrev[cpu] + PL.cpuSystemPrev[cpu] + PL.cpuGuestPrev[cpu] + PL.cpuGuestNicePrev[cpu] +
                         PL.cpuIrqPrev[cpu] + PL.cpuSoftIrqPrev[cpu] + PL.cpuStealPrev[cpu] + PL.cpuIowaitPrev[cpu] + PL.cpuNicePrev[cpu]);
         u64 dSys = (PL.cpuSystem[cpu] - PL.cpuSystemPrev[cpu]);
         u64 dNice = (PL.cpuNice[cpu] - PL.cpuNicePrev[cpu]);
         if (dTotal > 0) { sys = (double)dSys / dTotal * 100.0; low = (double)dNice / dTotal * 100.0; }
      }
      snprintf(tmp, sizeof(tmp), "%d:%5.1f%% sys:%5.1f%% low:%3.0f ", cpu, total, sys, low);
      strncat(buf, tmp, n - strlen(buf) - 1);
   }
}

static void Meter_setCaption(Meter* m) {
   switch (m->type) {
      case METER_MEMORY: setStr(&m->caption, "Mem"); break;
      case METER_SWAP: setStr(&m->caption, "Swp"); break;
      case METER_MEMORY_SWAP: setStr(&m->caption, "MemSwp"); break;
      case METER_TASKS: setStr(&m->caption, "Task counter"); break;
      case METER_LOAD_AVERAGE: setStr(&m->caption, "Load average"); break;
      case METER_UPTIME: setStr(&m->caption, "Uptime"); break;
      case METER_UPTIME_SECS: setStr(&m->caption, "Uptime (seconds)"); break;
      case METER_CLOCK: setStr(&m->caption, "Clock"); break;
      case METER_DATE: setStr(&m->caption, "Date"); break;
      case METER_DATE_TIME: setStr(&m->caption, "Date and Time"); break;
      case METER_HOSTNAME: setStr(&m->caption, "Hostname"); break;
      case METER_LOAD: setStr(&m->caption, "Load"); break;
      case METER_SYSTEM: setStr(&m->caption, "System"); break;
      case METER_HUGEPAGES: setStr(&m->caption, "HugePages"); break;
      case METER_BLANK: setStr(&m->caption, ""); break;
      case METER_BATTERY: setStr(&m->caption, "Battery"); break;
      case METER_CPU_AVERAGE: setStr(&m->caption, "CPU"); break;
      case METER_GPU: setStr(&m->caption, "GPU"); break;
      default: setStr(&m->caption, ""); break;
   }
}

static Meter* Meter_new(int type, int mode, int item) {
   Meter* m = calloc(1, sizeof(Meter));
   m->type = type;
   m->mode = mode ? mode : METER_MODE_BAR;
   m->item = item;
   Meter_setCaption(m);
   if (type >= METER_CPU_PERCORE || type == METER_CPU_AVERAGE) {
      /* CPU group meter: item selects which half / group */
      int half = PL.cpuCount / 2;
      if (item == 0) { m->cpuOffset = 0; m->ncpu = half; }
      else { m->cpuOffset = half; m->ncpu = PL.cpuCount - half; }
      /* the number of grid columns is encoded in the meter type name */
      m->ncols = 8;
      m->height = (m->ncpu + m->ncols - 1) / m->ncols;
   } else {
      m->height = 1;
   }
   return m;
}

static void Meter_delete(Meter* m) { if (m) { free(m->caption); free(m); } }

static void drawBarMeter(Meter* m, int x, int y, int w) {
   /* w is the total width including the name and brackets */
   int nameLen = (int)strlen(m->caption);
   int barW = w - nameLen - 2;
   if (barW < 0) barW = 0;
   attrset(CRT_color(COLOR_METER_TEXT));
   mvaddstr(y, x, m->caption);
   x += nameLen;
   attrset(CRT_color(COLOR_BAR_BORDER));
   addstr("[");
   x++;
   /* draw segments */
   int captionLen = (int)strlen(m->text);
   int capX = x + barW - captionLen;
   int segColors[8] = { EX_MEMORY_USED, EX_MEMORY_SHARED, EX_MEMORY_COMPRESSED,
                        EX_MEMORY_BUFFERS, EX_MEMORY_CACHE, EX_SWAP_USED,
                        EX_SWAP_CACHE, EX_SWAP_FRONT };
   int nItems = 4;
   double vals[8] = {0};
   if (m->type == METER_MEMORY) {
      vals[0] = (double)(PL.memUsed) / PL.memTotal;
      vals[1] = (double)(PL.memShared) / PL.memTotal;
      vals[2] = 0.0;
      vals[3] = (double)(PL.memBuffers) / PL.memTotal;
      vals[4] = (double)(PL.memCached) / PL.memTotal;
      nItems = 5;
   } else if (m->type == METER_SWAP) {
      vals[0] = (double)PL.swapUsed / (PL.swapTotal ? PL.swapTotal : 1);
      vals[1] = 0.0;
      vals[2] = 0.0;
      nItems = 1;
   }
   /* draw filled part */
   double acc = 0;
   for (int i = 0; i < nItems; i++) {
      double v = vals[i];
      if (v <= 0) continue;
      double start = acc, end = acc + v;
      if (end > 1) end = 1;
      int sx = x + (int)(start * barW);
      int ex = x + (int)(end * barW);
      if (ex > sx) {
         attrset(CRT_color(segColors[i]));
         for (int c = sx; c < ex; c++) mvaddch(y, c, '|');
      }
      acc += v;
      if (acc >= 1) break;
   }
   /* shadow */
   int used = (int)(acc * barW);
   if (used < barW) {
      attrset(CRT_color(COLOR_BAR_SHADOW));
      for (int c = x + used; c < x + barW; c++) mvaddch(y, c, '|');
   }
   /* caption */
   if (capX >= x) {
      attrset(CRT_color(m->type == METER_MEMORY ? COLOR_METER_VALUE : COLOR_BAR_SHADOW));
      char cap[128];
      snprintf(cap, sizeof(cap), "%.*s", barW, m->text);
      mvaddstr(y, capX, cap);
   }
   attrset(CRT_color(COLOR_BAR_BORDER));
   mvaddch(y, x + barW, ']');
}

static void drawTextMeter(Meter* m, int x, int y, int w) {
   attrset(CRT_color(COLOR_METER_TEXT));
   char cap[64];
   snprintf(cap, sizeof(cap), "%s: ", m->caption);
   mvaddstr(y, x, cap);
   int cx = x + strlen(cap);
   if (m->type == METER_TASKS) {
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddstr(y, cx, "Tasks: ");
      cx += 7;
      char b[64];
      snprintf(b, sizeof(b), "%d", PL.totalTasks);
      attrset(CRT_color(COLOR_METER_VALUE) | A_BOLD);
      mvaddstr(y, cx, b); cx += strlen(b);
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddstr(y, cx, ", "); cx += 2;
      snprintf(b, sizeof(b), "%d", PL.userlandThreads);
      attrset(CRT_color(COLOR_BRIGHT_GREEN) | A_BOLD);
      mvaddstr(y, cx, b); cx += strlen(b);
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddstr(y, cx, " thr"); cx += 4;
      if (PL.kernelThreads) {
         snprintf(b, sizeof(b), "%d", PL.kernelThreads);
         attrset(CRT_color(COLOR_METER_VALUE) | A_BOLD);
         mvaddstr(y, cx, b); cx += strlen(b);
         attrset(CRT_color(COLOR_METER_TEXT));
         mvaddstr(y, cx, " kthr"); cx += 5;
      } else {
         attrset(CRT_color(COLOR_PROCESS_SHADOW));
         mvaddstr(y, cx, ", 0 kthr"); cx += 8;
      }
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddstr(y, cx, "; "); cx += 2;
      snprintf(b, sizeof(b), "%d", PL.runningTasks);
      attrset(CRT_color(COLOR_BRIGHT_GREEN) | A_BOLD);
      mvaddstr(y, cx, b); cx += strlen(b);
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddstr(y, cx, " running");
   } else if (m->type == METER_LOAD_AVERAGE) {
      char b[64];
      snprintf(b, sizeof(b), "%5.2f ", PL.loadAvg[0]);
      attrset(CRT_color(COLOR_METER_VALUE) | A_BOLD);
      mvaddstr(y, cx, b); cx += strlen(b);
      snprintf(b, sizeof(b), "%5.2f ", PL.loadAvg[1]);
      attrset(CRT_color(COLOR_TEXT_MEAN_VALUE));
      mvaddstr(y, cx, b); cx += strlen(b);
      snprintf(b, sizeof(b), "%5.2f ", PL.loadAvg[2]);
      attrset(CRT_color(COLOR_TEXT_LAST_VALUE));
      mvaddstr(y, cx, b);
   } else if (m->type == METER_UPTIME) {
      char b[64];
      time_t up = time(NULL) - PL.bootTimeSecs;
      int d = up / 86400;
      int h = (up / 3600) % 24;
      int mi = (up / 60) % 60;
      int s = up % 60;
      if (d > 0) snprintf(b, sizeof(b), "%d days, %02d:%02d:%02d", d, h, mi, s);
      else snprintf(b, sizeof(b), "%02d:%02d:%02d", h, mi, s);
      attrset(CRT_color(COLOR_METER_VALUE) | A_BOLD);
      mvaddstr(y, cx, b);
   }
}

static void drawCPUMeter(Meter* m, int x, int y, int w, int row) {
   int N = m->ncols;
   int cellW = w / N;
   if (cellW < 5) cellW = 5;
   int barW = cellW - 5;
   if (barW < 0) barW = 0;
   int leftover = w - N * cellW;
   int xx = x;
   for (int i = 0; i < N; i++) {
      int cpu = m->cpuOffset + row * N + i;
      if (cpu >= m->cpuOffset + m->ncpu) break;
      /* caption */
      char cap[16];
      snprintf(cap, sizeof(cap), "%*d", 3, cpu);
      attrset(CRT_color(COLOR_METER_TEXT));
      mvaddnstr(y, xx, cap, cellW > 3 ? 3 : cellW);
      int cx = xx + 3;
      if (cellW >= 4) {
         attrset(CRT_color(COLOR_BAR_BORDER) | A_BOLD);
         mvaddch(y, cx, '[');
         cx++;
         /* bar */
         double v = 0;
         if (cpu < PL.cpuCount) {
            Meter tmp; memset(&tmp, 0, sizeof(tmp));
            tmp.cpuOffset = cpu; tmp.ncpu = 1;
            cpuMeterValues(&tmp);
            v = tmp.values[0];
         }
         int filled = (int)(v * barW / 100.0 + 0.5);
         if (filled > barW) filled = barW;
         for (int c = 0; c < barW; c++) {
            int color = COLOR_BAR_SHADOW;
            double frac = (double)(c + 1) / barW * 100.0;
            if (frac <= v) color = COLOR_CPU_METER_NORMAL;
            else if (v > 0 && (double)c / barW * 100.0 < v) color = COLOR_CPU_METER_NORMAL;
            attrset(CRT_color(color));
            mvaddch(y, cx + c, '|');
         }
         if (barW > 0) {
            /* caption text */
            char cap2[16];
            if (v >= 100) snprintf(cap2, sizeof(cap2), "100.");
            else if (v >= 10) snprintf(cap2, sizeof(cap2), "%.1f", v);
            else snprintf(cap2, sizeof(cap2), "%.1f%%", v);
            int cl = (int)strlen(cap2);
            if (cl > barW) cap2[barW] = '\0';
            cl = (int)strlen(cap2);
            attrset(CRT_color(COLOR_METER_VALUE));
            mvaddnstr(y, cx + barW - cl, cap2, cl);
         }
         attrset(CRT_color(COLOR_BAR_BORDER) | A_BOLD);
         mvaddch(y, cx + barW, ']');
      }
      xx += cellW;
      if (i < leftover && i < N - 1) { attrset(0); mvaddch(y, xx, ' '); xx++; }
   }
}

static void Meter_draw(Meter* m, int x, int y, int w) {
   if (m->type == METER_MEMORY || m->type == METER_SWAP || m->type == METER_MEMORY_SWAP) {
      /* update the values/text */
      if (m->type == METER_MEMORY) {
         double total = PL.memTotal ? (double)PL.memTotal : 1;
         char t[32], t2[32];
         printHumanSize(t, sizeof(t), (double)PL.memUsed);
         printHumanSize(t2, sizeof(t2), (double)PL.memTotal);
         snprintf(m->text, sizeof(m->text), "%s/%s", t, t2);
      } else {
         char t[32], t2[32];
         printHumanSize(t, sizeof(t), (double)PL.swapUsed);
         printHumanSize(t2, sizeof(t2), (double)PL.swapTotal);
         snprintf(m->text, sizeof(m->text), "%s/%s", t, t2);
      }
      drawBarMeter(m, x, y, w);
   } else if (m->type >= METER_CPU_PERCORE || m->type == METER_CPU_AVERAGE) {
      int rows = m->height;
      for (int r = 0; r < rows; r++)
         drawCPUMeter(m, x, y + r, w, r);
   } else {
      drawTextMeter(m, x, y, w);
   }
}
CEOF
echo ok"}

