   p->x = x; p->y = y; p->w = w; p->h = h; p->title = title;
}
static void Panel_free(Panel* p) { free(p->items); p->items = NULL; p->size = p->cap = 0; }
static void Panel_reserve(Panel* p, int n) {
   if (n > p->cap) {
      int nc = p->cap ? p->cap * 2 : 64;
      while (nc < n) nc *= 2;
      p->items = realloc(p->items, sizeof(Item) * nc);
      memset(p->items + p->cap, 0, sizeof(Item) * (nc - p->cap));
      p->cap = nc;
   }
}
static void Panel_add(Panel* p, void* data, const char* text) {
   Panel_reserve(p, p->size + 1);
