/* ---------------- header ---------------- */

typedef struct { Meter** meters; int n; int w; } HeaderCol;
static HeaderCol headerCols[4];
static int headerNcols = 2;
static int headerMaxHeight = 0;

static void Header_free(void) {
   for (int i = 0; i < 4; i++) {
      for (int j = 0; j < headerCols[i].n; j++) Meter_delete(headerCols[i].meters[j]);
      free(headerCols[i].meters);
      headerCols[i].meters = NULL; headerCols[i].n = 0;
   }
}

static int meterIndexByName(const char* name) {
   if (!name || !*name) return -1;
   if (strcmp(name, "Memory") == 0) return METER_MEMORY;
   if (strcmp(name, "Swap") == 0) return METER_SWAP;
   if (strcmp(name, "Tasks") == 0) return METER_TASKS;
   if (strcmp(name, "LoadAverage") == 0) return METER_LOAD_AVERAGE;
   if (strcmp(name, "Uptime") == 0) return METER_UPTIME;
   if (strcmp(name, "Clock") == 0) return METER_CLOCK;
   if (strcmp(name, "Date") == 0) return METER_DATE;
   if (strcmp(name, "DateAndTime") == 0) return METER_DATE_TIME;
   if (strcmp(name, "Hostname") == 0) return METER_HOSTNAME;
   if (strcmp(name, "Load") == 0) return METER_LOAD;
   if (strcmp(name, "AllCPUs") == 0 || strcmp(name, "CPU") == 0) return METER_CPU_AVERAGE;
   /* LeftCPUsN / RightCPUsN / AllCPUsN */
   int cols = 0;
   bool left = false, right = false, all = false;
   if (strncmp(name, "LeftCPUs", 8) == 0) { left = true; cols = atoi(name + 8); }
   else if (strncmp(name, "RightCPUs", 9) == 0) { right = true; cols = atoi(name + 9); }
   else if (strncmp(name, "AllCPUs", 7) == 0) { all = true; cols = atoi(name + 7); }
   else return -1;
   if (cols <= 0) return -1;
   (void)all;
   /* store as a CPU group meter: item 0 = left half, 1 = right half */
   MeterType t = left ? METER_CPU_PERCORE : (MeterType)(METER_CPU_PERCORE + 1);
   /* remember the column count globally for this item */
   cpuMeterCols[item ? 1 : 0] = cols;
   return t;
}

int cpuMeterCols[2] = { 8, 8 };

static void Header_build(Settings* s) {
   Header_free();
   headerNcols = s->nHeaderCols;
   for (int c = 0; c < headerNcols && c < 4; c++) {
      int n = s->colNMeters[c];
      headerCols[c].meters = calloc(n ? n : 1, sizeof(Meter*));
      headerCols[c].n = n;
      for (int j = 0; j < n; j++) {
         const char* name = s->colMeters[c][j];
         int mode = s->colMeterModes[c][j];
         int idx = meterIndexByName(name);
         int item = (idx == METER_CPU_PERCORE + 1) ? 1 : 0;
         Meter* m = Meter_new(idx, mode, item);
         if (idx >= METER_CPU_PERCORE) {
