{"command": "cat >> $HOME/htop/src/ui.c <<'CEOF'

/* ---------------- process list ---------------- */

typedef struct {
   Panel* panel;
   int screenIdx;          /* which screen this panel belongs to */
   bool filterActive;
   bool searchActive;
   char filterStr[256];
   char searchStr[256];
   int incIndent;          /* cursor position in the incremental buffer */
} ProcessPanel;

static ProcessPanel PP;
static bool treeMode = false;
static int  sortKeyCurrent = PERCENT_CPU;
static int  sortDirCurrent = -1;

static int curScreen = 0;

static ProcessField screenFieldsList[16][64];
static int screenNFields[16];

static void setScreenFields(int idx, ProcessField* fields, int n) {
   screenNFields[idx] = n;
   for (int i = 0; i < n && i < 64; i++) screenFieldsList[idx][i] = fields[i];
}

static int panelVisibleRows(void) {
   int yColHdr = (PL.settings->headerMargin ? 1 : 0) + headerMaxHeight + (PL.settings->headerMargin ? 1 : 0)
                 + (PL.settings->screenTabs ? 1 : 0);
   return LINES - 1 - (yColHdr + 1);
}

static void drawColumnHeader(int y, int screenIdx) {
   attrset(CRT_color(COLOR_PANEL_HDR));
   for (int i = 0; i < COLS; i++) mvaddch(y, i, ' ');
   int x = 0;
   ProcessField* fields = screenFieldsList[screenIdx];
   int n = screenNFields[screenIdx];
   for (int i = 0; i < n; i++) {
      ProcessField f = fields[i];
      const FieldInfo* fi = &fieldTable[f];
      char buf[128];
      int len = (int)strlen(fi->title);
      if (fi->align == ALIGN_RIGHT) {
         int off = fi->width > len ? fi->width - len : 0;
         if (off > 0) { attrset(CRT_color(COLOR_PANEL_HDR)); for (int k = 0; k < off; k++) mvaddch(y, x + k, ' '); }
         attrset(CRT_color(f == (ProcessField)sortKeyCurrent ? EX_PANEL_HDR_SORTED : COLOR_PANEL_HDR));
         mvaddnstr(y, x + off, fi->title, fi->width);
      } else {
         attrset(CRT_color(f == (ProcessField)sortKeyCurrent ? EX_PANEL_HDR_SORTED : COLOR_PANEL_HDR));
         mvaddnstr(y, x, fi->title, fi->width);
      }
      x += fi->width;
      /* separator / sort marker */
      if (f == (ProcessField)sortKeyCurrent) {
         attrset(CRT_color(EX_PANEL_HDR_SORTED));
         mvaddch(y, x, sortDirCurrent < 0 ? '-' : '+');
      } else {
         attrset(CRT_color(COLOR_PANEL_HDR));
         mvaddch(y, x, ' ');
      }
      x++;
      if (x > COLS) break;
   }
   attrset(0);
}

static void drawProcessRow(int y, Process* p, bool selected, int screenIdx) {
   ProcessField* fields = screenFieldsList[screenIdx];
   int n = screenNFields[screenIdx];
   attrset(CRT_color(selected ? COLOR_PANEL_SELECTION : COLOR_PROCESS));
   if (selected) {
      for (int i = 0; i < COLS; i++) mvaddch(y, i, ' ');
   }
   int x = 0;
   move(y, 0);
   for (int i = 0; i < n; i++) {
      ProcessField f = fields[i];
      if (x > COLS) break;
      if (selected) attrset(CRT_color(COLOR_PANEL_SELECTION));
      Process_writeField(p, f);
      /* compute the width consumed: the field's width + 1, except COMMAND */
      if (f == COMMAND) {
         const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
         x += (int)strlen(cmd);
      } else {
         x += fieldTable[f].width + 1;
      }
   }
   attrset(0);
}

static void drawTabs(int y, int screenIdx) {
   int x = 2;
   for (int i = 0; i < PL.settings->nScreens; i++) {
      bool active = (i == screenIdx);
      int base = active ? EX_TAB_ON : EX_TAB_OFF;
      int color = active ? EX_TAB_ON_COLOR : EX_TAB_OFF_COLOR;
      attrset(CRT_color(base));
      mvaddstr(y, x, "[");
      x++;
      attrset(CRT_color(color));
      mvaddstr(y, x, PL.settings->screenNames[i]);
      x += strlen(PL.settings->screenNames[i]);
      attrset(CRT_color(base));
      mvaddstr(y, x, "]");
      x++;
      attrset(0);
      mvaddch(y, x, ' ');
      x++;
   }
}
CEOF
echo ok"}

