#include "htop.h"

static const char* defaultFieldsStr = "0 48 17 18 38 39 40 2 46 47 49 1";
static const char* versionString = "3.5.0-dev-76f3fce";

static char* configPath(void) {
   const char* xdg = getenv("XDG_CONFIG_HOME");
   char* dir = NULL;
   if (xdg && *xdg) {
      size_t n = strlen(xdg) + 32;
      dir = malloc(n);
      snprintf(dir, n, "%s/htop", xdg);
   } else {
      const char* home = getenv("HOME");
      if (!home || !*home) return NULL;
      size_t n = strlen(home) + 32;
      dir = malloc(n);
      snprintf(dir, n, "%s/.config/htop", home);
   }
   size_t n = strlen(dir) + 16;
   char* path = malloc(n);
   snprintf(path, n, "%s/htoprc", dir);
   free(dir);
   return path;
}

/* strip a trailing token */
static char* trimToken(char** p, char sep) {
   char* s = *p;
   if (!s) return NULL;
   char* e = strchr(s, sep);
   if (e) { *e = '\0'; *p = e + 1; }
   else *p = s + strlen(s);
   while (*s == ' ') s++;
   return s;
}

static int readInt(const char* v, int def) {
   if (!v || !*v) return def;
   return (int)strtol(v, NULL, 10);
}

static bool readBool(const char* v, bool def) {
   if (!v || !*v) return def;
   return atoi(v) != 0;
}

static char* readStr(const char* v) { return v ? xStrdup(v) : NULL; }

/* read a screen definition block starting at "screen:NAME=..." */
static void parseScreen(Settings* s, char* name, char* value) {
   s->screenNames[s->nScreens] = xStrdup(name);
   s->screenFields[s->nScreens] = calloc(64, sizeof(ProcessField));
   int n = 0;
   char* p = value;
   while (p && *p) {
      char* tok = trimToken(&p, ' ');
      if (!tok || !*tok) continue;
      int f = fieldIndexByName(tok);
      if (f >= 0 && n < 63) s->screenFields[s->nScreens][n++] = (ProcessField)f;
   }
   s->screenSortKey[s->nScreens] = 0;
   s->screenTreeSortKey[s->nScreens] = PID;
   s->screenTreeView[s->nScreens] = 0;
   s->screenTreeViewAlwaysByPid[s->nScreens] = 0;
   s->screenSortDirection[s->nScreens] = -1;
   s->screenTreeSortDirection[s->nScreens] = 1;
   s->screenAllBranchesCollapsed[s->nScreens] = 0;
   s->nScreens++;
}

void Settings_setDefaultScreens(Settings* s) {
   s->nScreens = 0;
   static ProcessField mainFields[] = { PID, USER, PRIORITY, NICE, M_VIRT, M_RESIDENT,
                                        M_SHARE, STATE, PERCENT_CPU, PERCENT_MEM, TIME, COMMAND };
   static ProcessField ioFields[] = { PID, USER, IO_PRIORITY, IO_RATE, IO_READ_RATE, IO_WRITE_RATE, COMMAND };
   parseScreen(s, "Main", "");
   setScreenFields(0, mainFields, 12);
   parseScreen(s, "I/O", "");
   setScreenFields(1, ioFields, 7);
   s->screenSortKey[0] = PERCENT_CPU;
   s->screenTreeSortKey[0] = PID;
   s->screenSortDirection[0] = -1;
   s->screenTreeSortDirection[0] = 1;
   s->screenSortKey[1] = IO_RATE;
   s->screenTreeSortKey[1] = PID;
   s->screenSortDirection[1] = -1;
   s->screenTreeSortDirection[1] = 1;
}

void Settings_init(Settings* s) {
   memset(s, 0, sizeof(*s));
   s->version = xStrdup(versionString);
   s->hideKernelThreads = 1;
   s->hideUserlandThreads = 0;
   s->hideRunningInContainer = 0;
   s->shadowOtherUsers = 0;
   s->showThreadNames = 0;
   s->showProgramPath = 1;
   s->highlightBaseName = 0;
   s->highlightDeletedExe = 1;
   s->shadowDistPathPrefix = 0;
   s->highlightMegabytes = 1;
   s->highlightThreads = 1;
   s->highlightChanges = 0;
   s->highlightChangesDelaySecs = 5;
   s->findCommInCmdline = 1;
   s->stripExeFromCmdline = 1;
   s->showMergedCommand = 0;
   s->headerMargin = 1;
   s->screenTabs = 1;
   s->detailedCpuTime = 0;
   s->cpuCountFromOne = 0;
   s->showCpuUsage = 1;
   s->showCpuFrequency = 0;
   s->showCachedMemory = 1;
   s->updateProcessNames = 0;
   s->accountGuestInCpuMeter = 0;
   s->colorScheme = 0;
   s->enableMouse = 1;
   s->delay = 15;
   s->hideFunctionBar = 0;
   s->headerLayout = xStrdup("two_50_50");
   s->legacyFields = xStrdup(defaultFieldsStr);
   s->treeView = 0;
   s->sortKey = PERCENT_CPU;
   s->treeSortKey = PID;
   s->sortDirection = -1;
   s->treeSortDirection = 1;
   s->treeViewAlwaysByPid = 0;
   s->allBranchesCollapsed = 0;
   s->nHeaderCols = 2;
   s->colNMeters[0] = 3; s->colNMeters[1] = 4;
   static const char* m0[] = { "LeftCPUs8", "Memory", "Swap" };
   static const char* m1[] = { "RightCPUs8", "Tasks", "LoadAverage", "Uptime" };
   s->colMeters[0] = calloc(4, sizeof(char*));
   s->colMeters[1] = calloc(5, sizeof(char*));
   for (int i = 0; i < 3; i++) s->colMeters[0][i] = xStrdup(m0[i]);
   for (int i = 0; i < 4; i++) s->colMeters[1][i] = xStrdup(m1[i]);
   s->colMeterModes[0] = calloc(4, sizeof(int));
   s->colMeterModes[1] = calloc(5, sizeof(int));
   s->colMeterModes[0][0] = 1; s->colMeterModes[0][1] = 1; s->colMeterModes[0][2] = 1;
   s->colMeterModes[1][0] = 1; s->colMeterModes[1][1] = 2; s->colMeterModes[1][2] = 2; s->colMeterModes[1][3] = 2;
   Settings_setDefaultScreens(s);
   /* read the config file */
   char* path = configPath();
   if (!path) return;
   FILE* f = fopen(path, "r");
   if (!f) { free(path); return; }
   char line[4096];
   char lastScreen[64] = "";
   while (fgets(line, sizeof(line), f)) {
      line[strcspn(line, "\n")] = '\0';
      if (line[0] == '#' || line[0] == '\0') continue;
      char* eq = strchr(line, '=');
      if (!eq) continue;
      *eq = '\0';
      char* key = line;
      char* val = eq + 1;
      if (strncmp(key, "screen:", 7) == 0) {
         snprintf(lastScreen, sizeof(lastScreen), "%s", key + 7);
         int found = -1;
         for (int i = 0; i < s->nScreens; i++)
            if (strcmp(s->screenNames[i], lastScreen) == 0) { found = i; break; }
         if (found < 0) {
            parseScreen(s, lastScreen, val);
            found = s->nScreens - 1;
         } else {
            int n = 0;
            char* p = val;
            while (p && *p) {
               char* tok = trimToken(&p, ' ');
               if (!tok || !*tok) continue;
               int fi = fieldIndexByName(tok);
               if (fi >= 0 && n < 63) s->screenFields[found][n++] = (ProcessField)fi;
            }
            screenNFields[found] = n;
         }
         continue;
      }
      if (key[0] == '.') {
         if (!lastScreen[0]) continue;
         int found = -1;
         for (int i = 0; i < s->nScreens; i++)
            if (strcmp(s->screenNames[i], lastScreen) == 0) { found = i; break; }
         if (found < 0) continue;
         const char* k = key + 1;
         if (strcmp(k, "sort_key") == 0) {
            int fi = fieldIndexByName(val);
            s->screenSortKey[found] = fi >= 0 ? fi : s->screenSortKey[found];
         } else if (strcmp(k, "tree_sort_key") == 0) {
            int fi = fieldIndexByName(val);
            s->screenTreeSortKey[found] = fi >= 0 ? fi : s->screenTreeSortKey[found];
         } else if (strcmp(k, "tree_view_always_by_pid") == 0) {
            s->screenTreeViewAlwaysByPid[found] = atoi(val);
         } else if (strcmp(k, "tree_view") == 0) {
            s->screenTreeView[found] = atoi(val);
         } else if (strcmp(k, "sort_direction") == 0) {
            s->screenSortDirection[found] = atoi(val);
         } else if (strcmp(k, "tree_sort_direction") == 0) {
            s->screenTreeSortDirection[found] = atoi(val);
         } else if (strcmp(k, "all_branches_collapsed") == 0) {
            s->screenAllBranchesCollapsed[found] = atoi(val);
         }
         continue;
      }
      if (strcmp(key, "hide_kernel_threads") == 0) s->hideKernelThreads = readBool(val, 1);
      else if (strcmp(key, "hide_userland_threads") == 0) s->hideUserlandThreads = readBool(val, 0);
      else if (strcmp(key, "hide_running_in_container") == 0) s->hideRunningInContainer = readBool(val, 0);
      else if (strcmp(key, "shadow_other_users") == 0) s->shadowOtherUsers = readBool(val, 0);
      else if (strcmp(key, "show_thread_names") == 0) s->showThreadNames = readBool(val, 0);
      else if (strcmp(key, "show_program_path") == 0) s->showProgramPath = readBool(val, 1);
      else if (strcmp(key, "highlight_base_name") == 0) s->highlightBaseName = readBool(val, 0);
      else if (strcmp(key, "highlight_deleted_exe") == 0) s->highlightDeletedExe = readBool(val, 1);
      else if (strcmp(key, "shadow_distribution_path_prefix") == 0) s->shadowDistPathPrefix = readBool(val, 0);
      else if (strcmp(key, "highlight_megabytes") == 0) s->highlightMegabytes = readBool(val, 1);
      else if (strcmp(key, "highlight_threads") == 0) s->highlightThreads = readBool(val, 1);
      else if (strcmp(key, "highlight_changes") == 0) s->highlightChanges = readBool(val, 0);
      else if (strcmp(key, "highlight_changes_delay_secs") == 0) s->highlightChangesDelaySecs = readInt(val, 5);
      else if (strcmp(key, "find_comm_in_cmdline") == 0) s->findCommInCmdline = readBool(val, 1);
      else if (strcmp(key, "strip_exe_from_cmdline") == 0) s->stripExeFromCmdline = readBool(val, 1);
      else if (strcmp(key, "show_merged_command") == 0) s->showMergedCommand = readBool(val, 0);
      else if (strcmp(key, "header_margin") == 0) s->headerMargin = readInt(val, 1);
      else if (strcmp(key, "screen_tabs") == 0) s->screenTabs = readBool(val, 1);
      else if (strcmp(key, "detailed_cpu_time") == 0) s->detailedCpuTime = readBool(val, 0);
      else if (strcmp(key, "cpu_count_from_one") == 0) s->cpuCountFromOne = readBool(val, 0);
      else if (strcmp(key, "show_cpu_usage") == 0) s->showCpuUsage = readBool(val, 1);
      else if (strcmp(key, "show_cpu_frequency") == 0) s->showCpuFrequency = readBool(val, 0);
      else if (strcmp(key, "show_cached_memory") == 0) s->showCachedMemory = readBool(val, 1);
      else if (strcmp(key, "update_process_names") == 0) s->updateProcessNames = readBool(val, 0);
      else if (strcmp(key, "account_guest_in_cpu_meter") == 0) s->accountGuestInCpuMeter = readBool(val, 0);
      else if (strcmp(key, "color_scheme") == 0) s->colorScheme = readInt(val, 0);
      else if (strcmp(key, "enable_mouse") == 0) s->enableMouse = readBool(val, 1);
      else if (strcmp(key, "delay") == 0) s->delay = readInt(val, 15);
      else if (strcmp(key, "hide_function_bar") == 0) s->hideFunctionBar = readBool(val, 0);
      else if (strcmp(key, "header_layout") == 0) s->headerLayout = readStr(val);
      else if (strcmp(key, "fields") == 0) s->legacyFields = readStr(val);
      else if (strcmp(key, "tree_view") == 0) s->treeView = readBool(val, 0);
      else if (strcmp(key, "sort_key") == 0) s->sortKey = readInt(val, PERCENT_CPU);
      else if (strcmp(key, "tree_sort_key") == 0) s->treeSortKey = readInt(val, PID);
      else if (strcmp(key, "sort_direction") == 0) s->sortDirection = readInt(val, -1);
      else if (strcmp(key, "tree_sort_direction") == 0) s->treeSortDirection = readInt(val, 1);
      else if (strcmp(key, "tree_view_always_by_pid") == 0) s->treeViewAlwaysByPid = readBool(val, 0);
      else if (strcmp(key, "all_branches_collapsed") == 0) s->allBranchesCollapsed = readBool(val, 0);
      else if (strncmp(key, "column_meters_", 14) == 0) {
         int c = atoi(key + 14);
         if (c < 0 || c >= 4) continue;
         int n = 0;
         char* p = val;
         while (p && *p) {
            char* tok = trimToken(&p, ' ');
            if (!tok || !*tok) continue;
            if (n < 15) s->colMeters[c][n++] = xStrdup(tok);
         }
         s->colNMeters[c] = n;
      } else if (strncmp(key, "column_meter_modes_", 19) == 0) {
         int c = atoi(key + 19);
         if (c < 0 || c >= 4) continue;
         int n = 0;
         char* p = val;
         while (p && *p) {
            char* tok = trimToken(&p, ' ');
            if (!tok || !*tok) continue;
            if (n < 15) s->colMeterModes[c][n++] = atoi(tok);
         }
      }
   }
   fclose(f);
   /* validate: the modes count must match the meters count */
   for (int c = 0; c < 4; c++) {
      int modes = 0;
      for (int i = 0; i < 15; i++) if (s->colMeterModes[c][i]) modes++;
      /* if the modes are a contiguous prefix, accept; otherwise fall back */
      bool ok = true;
      for (int i = s->colNMeters[c]; i < 15; i++) if (s->colMeterModes[c][i]) ok = false;
      if (!ok) { /* reset to the defaults for this column */ }
   }
   /* header layout: the number of columns */
   const char* hl = s->headerLayout;
   if (strncmp(hl, "two_", 4) == 0) s->nHeaderCols = 2;
   else if (strncmp(hl, "three_", 6) == 0) s->nHeaderCols = 3;
   else if (strncmp(hl, "four_", 5) == 0) s->nHeaderCols = 4;
   else s->nHeaderCols = 1;
   free(path);
}

void Settings_write(Settings* s) {
   char* path = configPath();
   if (!path) return;
   char dir[4096];
   snprintf(dir, sizeof(dir), "%s", path);
   char* slash = strrchr(dir, '/');
   if (slash) { *slash = '\0'; mkdir(dir, 0700); }
   FILE* f = fopen(path, "w");
   if (!f) { free(path); return; }
   chmod(path, 0600);
   fprintf(f, "# Beware! This file is rewritten by htop when settings are changed in the interface.\n");
   fprintf(f, "# The parser is also very primitive, and not human-friendly.\n");
   fprintf(f, "htop_version=%s\n", versionString);
   fprintf(f, "config_reader_min_version=3\n");
   fprintf(f, "fields=%s\n", s->legacyFields ? s->legacyFields : defaultFieldsStr);
   fprintf(f, "hide_kernel_threads=%d\n", s->hideKernelThreads ? 1 : 0);
   fprintf(f, "hide_userland_threads=%d\n", s->hideUserlandThreads ? 1 : 0);
   fprintf(f, "hide_running_in_container=%d\n", s->hideRunningInContainer ? 1 : 0);
   fprintf(f, "shadow_other_users=%d\n", s->shadowOtherUsers ? 1 : 0);
   fprintf(f, "show_thread_names=%d\n", s->showThreadNames ? 1 : 0);
   fprintf(f, "show_program_path=%d\n", s->showProgramPath ? 1 : 0);
   fprintf(f, "highlight_base_name=%d\n", s->highlightBaseName ? 1 : 0);
   fprintf(f, "highlight_deleted_exe=%d\n", s->highlightDeletedExe ? 1 : 0);
   fprintf(f, "shadow_distribution_path_prefix=%d\n", s->shadowDistPathPrefix ? 1 : 0);
   fprintf(f, "highlight_megabytes=%d\n", s->highlightMegabytes ? 1 : 0);
   fprintf(f, "highlight_threads=%d\n", s->highlightThreads ? 1 : 0);
   fprintf(f, "highlight_changes=%d\n", s->highlightChanges ? 1 : 0);
   fprintf(f, "highlight_changes_delay_secs=%d\n", s->highlightChangesDelaySecs);
   fprintf(f, "find_comm_in_cmdline=%d\n", s->findCommInCmdline ? 1 : 0);
   fprintf(f, "strip_exe_from_cmdline=%d\n", s->stripExeFromCmdline ? 1 : 0);
   fprintf(f, "show_merged_command=%d\n", s->showMergedCommand ? 1 : 0);
   fprintf(f, "header_margin=%d\n", s->headerMargin);
   fprintf(f, "screen_tabs=%d\n", s->screenTabs ? 1 : 0);
   fprintf(f, "detailed_cpu_time=%d\n", s->detailedCpuTime ? 1 : 0);
   fprintf(f, "cpu_count_from_one=%d\n", s->cpuCountFromOne ? 1 : 0);
   fprintf(f, "show_cpu_usage=%d\n", s->showCpuUsage ? 1 : 0);
   fprintf(f, "show_cpu_frequency=%d\n", s->showCpuFrequency ? 1 : 0);
   fprintf(f, "show_cached_memory=%d\n", s->showCachedMemory ? 1 : 0);
   fprintf(f, "update_process_names=%d\n", s->updateProcessNames ? 1 : 0);
   fprintf(f, "account_guest_in_cpu_meter=%d\n", s->accountGuestInCpuMeter ? 1 : 0);
   fprintf(f, "color_scheme=%d\n", s->colorScheme);
   fprintf(f, "enable_mouse=%d\n", s->enableMouse ? 1 : 0);
   fprintf(f, "delay=%d\n", s->delay);
   fprintf(f, "hide_function_bar=%d\n", s->hideFunctionBar ? 1 : 0);
   fprintf(f, "header_layout=%s\n", s->headerLayout);
   for (int c = 0; c < 4; c++) {
      if (s->colNMeters[c] <= 0) continue;
      fprintf(f, "column_meters_%d=", c);
      for (int i = 0; i < s->colNMeters[c]; i++)
         fprintf(f, "%s%s", i ? " " : "", s->colMeters[c][i]);
      fprintf(f, "\n");
      fprintf(f, "column_meter_modes_%d=", c);
      for (int i = 0; i < s->colNMeters[c]; i++)
         fprintf(f, "%s%d", i ? " " : "", s->colMeterModes[c][i]);
      fprintf(f, "\n");
   }
   fprintf(f, "tree_view=%d\n", s->treeView ? 1 : 0);
   fprintf(f, "sort_key=%d\n", s->sortKey);
   fprintf(f, "tree_sort_key=%d\n", s->treeSortKey);
   fprintf(f, "sort_direction=%d\n", s->sortDirection);
   fprintf(f, "tree_sort_direction=%d\n", s->treeSortDirection);
   fprintf(f, "tree_view_always_by_pid=%d\n", s->treeViewAlwaysByPid ? 1 : 0);
   fprintf(f, "all_branches_collapsed=%d\n", s->allBranchesCollapsed ? 1 : 0);
   for (int i = 0; i < s->nScreens; i++) {
      fprintf(f, "screen:%s=", s->screenNames[i]);
      int n = screenNFields[i];
      for (int j = 0; j < n; j++)
         fprintf(f, "%s%s", j ? " " : "", fieldTable[screenFieldsList[i][j]].name);
      fprintf(f, "\n");
      fprintf(f, ".sort_key=%s\n", fieldTable[s->screenSortKey[i]].name);
      fprintf(f, ".tree_sort_key=%s\n", fieldTable[s->screenTreeSortKey[i]].name);
      fprintf(f, ".tree_view_always_by_pid=%d\n", s->screenTreeViewAlwaysByPid[i]);
      fprintf(f, ".tree_view=%d\n", s->screenTreeView[i]);
      fprintf(f, ".sort_direction=%d\n", s->screenSortDirection[i]);
      fprintf(f, ".tree_sort_direction=%d\n", s->screenTreeSortDirection[i]);
      fprintf(f, ".all_branches_collapsed=%d\n", s->screenAllBranchesCollapsed[i]);
   }
   fclose(f);
   free(path);
}
CEOF
echo ok"}

actions.command:
cat > $HOME/htop/src/settings.c <<'CEOF'
#include "htop.h"

static const char* defaultFieldsStr = "0 48 17 18 38 39 40 2 46 47 49 1";
static const char* versionString = "3.5.0-dev-76f3fce";

static char* configPath(void) {
   const char* xdg = getenv("XDG_CONFIG_HOME");
   char* dir = NULL;
   if (xdg && *xdg) {
      size_t n = strlen(xdg) + 32;
      dir = malloc(n);
      snprintf(dir, n, "%s/htop", xdg);
   } else {
      const char* home = getenv("HOME");
      if (!home || !*home) return NULL;
      size_t n = strlen(home) + 32;
      dir = malloc(n);
      snprintf(dir, n, "%s/.config/htop", home);
   }
   size_t n = strlen(dir) + 16;
   char* path = malloc(n);
   snprintf(path, n, "%s/htoprc", dir);
   free(dir);
   return path;
}

/* strip a trailing token */
static char* trimToken(char** p, char sep) {
   char* s = *p;
   if (!s) return NULL;
   char* e = strchr(s, sep);
   if (e) { *e = '\0'; *p = e + 1; }
   else *p = s + strlen(s);
   while (*s == ' ') s++;
   return s;
}

static int readInt(const char* v, int def) {
   if (!v || !*v) return def;
   return (int)strtol(v, NULL, 10);
}

static bool readBool(const char* v, bool def) {
   if (!v || !*v) return def;
   return atoi(v) != 0;
}

static char* readStr(const char* v) { return v ? xStrdup(v) : NULL; }

/* read a screen definition block starting at "screen:NAME=..." */
static void parseScreen(Settings* s, char* name, char* value) {
   s->screenNames[s->nScreens] = xStrdup(name);
   s->screenFields[s->nScreens] = calloc(64, sizeof(ProcessField));
   int n = 0;
   char* p = value;
   while (p && *p) {
      char* tok = trimToken(&p, ' ');
      if (!tok || !*tok) continue;
      int f = fieldIndexByName(tok);
      if (f >= 0 && n < 63) s->screenFields[s->nScreens][n++] = (ProcessField)f;
   }
   s->screenSortKey[s->nScreens] = 0;
   s->screenTreeSortKey[s->nScreens] = PID;
   s->screenTreeView[s->nScreens] = 0;
   s->screenTreeViewAlwaysByPid[s->nScreens] = 0;
   s->screenSortDirection[s->nScreens] = -1;
   s->screenTreeSortDirection[s->nScreens] = 1;
   s->screenAllBranchesCollapsed[s->nScreens] = 0;
   s->nScreens++;
}

void Settings_setDefaultScreens(Settings* s) {
   s->nScreens = 0;
   static ProcessField mainFields[] = { PID, USER, PRIORITY, NICE, M_VIRT, M_RESIDENT,
                                        M_SHARE, STATE, PERCENT_CPU, PERCENT_MEM, TIME, COMMAND };
   static ProcessField ioFields[] = { PID, USER, IO_PRIORITY, IO_RATE, IO_READ_RATE, IO_WRITE_RATE, COMMAND };
   parseScreen(s, "Main", "");
   setScreenFields(0, mainFields, 12);
   parseScreen(s, "I/O", "");
   setScreenFields(1, ioFields, 7);
   s->screenSortKey[0] = PERCENT_CPU;
   s->screenTreeSortKey[0] = PID;
   s->screenSortDirection[0] = -1;
   s->screenTreeSortDirection[0] = 1;
   s->screenSortKey[1] = IO_RATE;
   s->screenTreeSortKey[1] = PID;
   s->screenSortDirection[1] = -1;
   s->screenTreeSortDirection[1] = 1;
}

