/* ---------------- process list update ---------------- */

static bool listVisible(Process* p) {
   if (PL.settings->hideKernelThreads && p->isKernelThread) return false;
   if (PL.settings->hideUserlandThreads && p->isUserlandThread) return false;
   if (PL.settings->hideRunningInContainer && p->isContainerProcess) return false;
   if (PL.settings->shadowOtherUsers && p->st_uid != myUid) return false;
   if (filterUserSet && p->st_uid != filterUid) return false;
   if (nPidList > 0) {
      bool found = false;
      for (int i = 0; i < nPidList; i++) if (pidList[i] == p->pid) { found = true; break; }
      if (!found) return false;
   }
   if (nFilterTerms > 0) {
      const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
      bool any = false;
      for (int i = 0; i < nFilterTerms; i++) {
         if (strcasestr(cmd, filterTerms[i])) { any = true; break; }
      }
      if (!any) return false;
   }
   return true;
}

static void readSystemInfo(void) {
   /* /proc/stat */
   char buf[65536];
   FILE* f = fopen("/proc/stat", "r");
   if (f) {
      int cpuIdx = -1;
      while (fgets(buf, sizeof(buf), f)) {
         if (strncmp(buf, "cpu ", 4) == 0) {
            u64 v[10] = {0};
            sscanf(buf, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &v[0],&v[1],&v[2],&v[3],&v[4],&v[5],&v[6],&v[7],&v[8],&v[9]);
            PL.cpuUserTotal[0] = v[0]; PL.cpuNiceTotal[0] = v[1];
            PL.cpuSystemTotal[0] = v[2]; PL.cpuIdleTotal[0] = v[3];
            PL.cpuIowaitTotal[0] = v[4]; PL.cpuIrqTotal[0] = v[5];
            PL.cpuSoftIrqTotal[0] = v[6]; PL.cpuStealTotal[0] = v[7];
            PL.cpuGuestTotal[0] = v[8]; PL.cpuGuestNiceTotal[0] = v[9];
         } else if (strncmp(buf, "cpu", 3) == 0 && isdigit((unsigned char)buf[3])) {
            cpuIdx = atoi(buf + 3);
            if (cpuIdx >= 0 && cpuIdx < PL.cpuCount) {
               u64 v[10] = {0};
               sscanf(buf, "cpu%d %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                      &cpuIdx,&v[0],&v[1],&v[2],&v[3],&v[4],&v[5],&v[6],&v[7],&v[8],&v[9]);
               PL.cpuUser[cpuIdx] = v[0]; PL.cpuNice[cpuIdx] = v[1];
               PL.cpuSystem[cpuIdx] = v[2]; PL.cpuIdle[cpuIdx] = v[3];
               PL.cpuIowait[cpuIdx] = v[4]; PL.cpuIrq[cpuIdx] = v[5];
               PL.cpuSoftIrq[cpuIdx] = v[6]; PL.cpuSteal[cpuIdx] = v[7];
               PL.cpuGuest[cpuIdx] = v[8]; PL.cpuGuestNice[cpuIdx] = v[9];
            }
         } else if (strncmp(buf, "btime ", 6) == 0) {
            PL.bootTimeSecs = strtoull(buf + 6, NULL, 10);
         }
      }
      fclose(f);
   }
   /* meminfo */
   f = fopen("/proc/meminfo", "r");
   if (f) {
      while (fgets(buf, sizeof(buf), f)) {
         u64 v = 0;
         if (sscanf(buf, "MemTotal: %llu kB", &v) == 1) PL.memTotal = v;
         else if (sscanf(buf, "MemFree: %llu kB", &v) == 1) PL.memFree = v;
         else if (sscanf(buf, "MemAvailable: %llu kB", &v) == 1) PL.memAvailable = v;
         else if (sscanf(buf, "Buffers: %llu kB", &v) == 1) PL.memBuffers = v;
         else if (sscanf(buf, "Cached: %llu kB", &v) == 1) PL.memCached = v;
         else if (sscanf(buf, "SReclaimable: %llu kB", &v) == 1) PL.memCachedTotal = v;
         else if (sscanf(buf, "Shmem: %llu kB", &v) == 1) PL.memShared = v;
      }
      fclose(f);
   }
   PL.memUsed = PL.memTotal - PL.memFree - PL.memBuffers - PL.memCached - PL.memCachedTotal;
   if ((long long)PL.memUsed < 0) PL.memUsed = 0;
   /* swap */
   f = fopen("/proc/meminfo", "r");
   if (f) {
      while (fgets(buf, sizeof(buf), f)) {
         u64 v = 0;
         if (sscanf(buf, "SwapTotal: %llu kB", &v) == 1) PL.swapTotal = v;
         else if (sscanf(buf, "SwapFree: %llu kB", &v) == 1) PL.swapFree = v;
      }
      fclose(f);
   }
   PL.swapUsed = PL.swapTotal - PL.swapFree;
   /* loadavg */
   f = fopen("/proc/loadavg", "r");
   if (f) {
      if (fgets(buf, sizeof(buf), f)) {
         sscanf(buf, "%lf %lf %lf", &PL.loadAvg[0], &PL.loadAvg[1], &PL.loadAvg[2]);
      }
      fclose(f);
   }
}

static void ProcessList_update(void) {
   struct timeval now;
   gettimeofday(&now, NULL);
   double interval = (double)(now.tv_sec - PL.lastUpdate.tv_sec) + (double)(now.tv_usec - PL.lastUpdate.tv_usec) / 1e6;
   if (interval < 0.001) interval = 0.001;
   /* save the previous cpu values */
   for (int i = 0; i < PL.cpuCount; i++) {
      PL.cpuUserPrev[i] = PL.cpuUser[i]; PL.cpuSystemPrev[i] = PL.cpuSystem[i];
      PL.cpuGuestPrev[i] = PL.cpuGuest[i]; PL.cpuGuestNicePrev[i] = PL.cpuGuestNice[i];
      PL.cpuIdlePrev[i] = PL.cpuIdle[i]; PL.cpuIrqPrev[i] = PL.cpuIrq[i];
      PL.cpuSoftIrqPrev[i] = PL.cpuSoftIrq[i]; PL.cpuStealPrev[i] = PL.cpuSteal[i];
      PL.cpuIowaitPrev[i] = PL.cpuIowait[i]; PL.cpuNicePrev[i] = PL.cpuNice[i];
   }
   PL.lastUpdate = now;
   readSystemInfo();
   /* scan processes */
   PL.totalTasks = 0; PL.userlandThreads = 0; PL.kernelThreads = 0; PL.runningTasks = 0;
   DIR* d = opendir("/proc");
   if (!d) return;
   struct dirent* e;
   int seen[32768];
   memset(seen, 0, sizeof(seen));
   Process* found[4096];
   int nFound = 0;
   while ((e = readdir(d)) != NULL) {
      if (e->d_name[0] < '0' || e->d_name[0] > '9') continue;
      int pid = atoi(e->d_name);
      if (pid <= 0) continue;
      if (nPidList > 0) {
         bool ok = false;
         for (int i = 0; i < nPidList; i++) if (pidList[i] == pid) { ok = true; break; }
         if (!ok) continue;
      }
      if (nFound >= 4096) break;
      Process* p = NULL;
      for (int i = 0; i < PL.count; i++) if (PL.procs[i].pid == pid) { p = &PL.procs[i]; break; }
      bool isNew = false;
      if (!p) {
         for (int i = 0; i < PL.count; i++) {
            if (!PL.procs[i].updated) { p = &PL.procs[i]; memset(p, 0, sizeof(*p)); p->pid = pid; isNew = true; break; }
         }
         if (!p && PL.count < MAX_PROCS) { p = &PL.procs[PL.count]; PL.count++; memset(p, 0, sizeof(*p)); p->pid = pid; isNew = true; }
      }
      if (!p) continue;
      p->updated = true;
      seen[pid & 32767] = 1;
      /* save the previous values */
      p->prev_utime = p->utime; p->prev_stime = p->stime;
      p->prev_rbytes = p->rbytes; p->prev_wbytes = p->wbytes; p->prev_cnclwb = p->cnclwb;
      p->prev_syscr = p->syscr; p->prev_syscw = p->syscw;
      p->prev_minflt = p->minflt; p->prev_cminflt = p->cminflt;
      p->prev_majflt = p->majflt; p->prev_cmajflt = p->cmajflt;
      if (!readStat(pid, p)) { p->updated = false; continue; }
      readStatm(p);
      readIo(p);
      readStatus(p);
      readMisc(p);
      if (isNew || PL.settings->updateProcessNames) readLinks(p);
      /* user name */
      struct passwd* pw = getpwuid((uid_t)p->st_uid);
      char ub[64];
      if (pw && pw->pw_name) snprintf(ub, sizeof(ub), "%s", pw->pw_name);
      else snprintf(ub, sizeof(ub), "%d", p->st_uid);
      setStr(&p->user, ub);
      p->isRoot = (p->st_uid == 0);
      p->isKernelThread = (p->pid <= 4) ? false : false;
