static void handleKey(int ch) {
   Panel* p = PP.panel;
   Settings* s = PL.settings;
   if (incSearchMode || incFilterMode) {
      doSearchChar(ch);
      return;
   }
   if (showSortMenu) {
      switch (ch) {
         case KEY_UP: case 'k': if (sortPanel.selected > 0) sortPanel.selected--; break;
         case KEY_DOWN: case 'j': if (sortPanel.selected < sortPanel.size - 1) sortPanel.selected++; break;
         case '\r': case '\n': case KEY_ENTER: {
            if (sortPanel.selected < sortPanel.size) {
               ProcessField f = (ProcessField)(long)sortPanel.items[sortPanel.selected].data;
               if (treeMode) s->screenTreeSortKey[curScreen] = f;
               else s->screenSortKey[curScreen] = f;
               setSortKey(f, 0);
            }
            showSortMenu = false;
            break;
         }
         case 27: showSortMenu = false; break;
         default: break;
      }
      return;
   }
   if (showKillMenu) {
      switch (ch) {
         case KEY_UP: case 'k': if (killPanel.selected > 0) killPanel.selected--; break;
         case KEY_DOWN: case 'j': if (killPanel.selected < killPanel.size - 1) killPanel.selected++; break;
         case '\r': case '\n': case KEY_ENTER:
            if (killPanel.selected < killPanel.size) sendSignal((int)(long)killPanel.items[killPanel.selected].data);
            showKillMenu = false;
            break;
         case 27: showKillMenu = false; break;
         default: break;
      }
      return;
   }
   switch (ch) {
      case KEY_UP: case 'k':
         if (p->selected > 0) p->selected--;
         break;
      case KEY_DOWN: case 'j':
         if (p->selected < p->size - 1) p->selected++;
         break;
      case KEY_LEFT:
         if (p->scroll > 0) p->scroll--;
         break;
      case KEY_RIGHT:
         p->scroll++;
         break;
      case KEY_PPAGE: {
         int rows = panelVisibleRows();
         p->selected -= rows;
         if (p->selected < 0) p->selected = 0;
         break;
      }
      case KEY_NPAGE: {
         int rows = panelVisibleRows();
         p->selected += rows;
         if (p->selected > p->size - 1) p->selected = p->size - 1;
         break;
      }
      case KEY_HOME: p->selected = 0; break;
      case KEY_END: p->selected = p->size - 1; break;
      case ' ':
         if (p->selected >= 0 && p->selected < p->size) {
            Process* proc = (Process*)p->items[p->selected].data;
            proc->tagged = !proc->tagged;
         }
         break;
      case 'U': {
         for (int i = 0; i < p->size; i++) ((Process*)p->items[i].data)->tagged = false;
         break;
      }
      case 'c': {
         /* tag this process and its children */
         if (p->selected >= 0 && p->selected < p->size) {
            Process* proc = (Process*)p->items[p->selected].data;
            for (int i = 0; i < p->size; i++) {
               Process* q = (Process*)p->items[i].data;
               if (q->ppid == proc->pid) q->tagged = true;
            }
         }
         break;
      }
      case '\t':
         curScreen = (curScreen + 1) % s->nScreens;
         applyScreen(curScreen);
         break;
      case KEY_BTAB:
         curScreen = (curScreen + s->nScreens - 1) % s->nScreens;
         applyScreen(curScreen);
         break;
      case 't': toggleTree(); break;
      case 'T': setSortKey(TIME, 0); break;
      case 'M': setSortKey(PERCENT_MEM, 0); break;
      case 'P': setSortKey(PID, 0); break;
      case 'N': setSortKey(PID, 0); break;
      case 'I': sortDirCurrent = -sortDirCurrent; s->screenSortDirection[curScreen] = sortDirCurrent; break;
      case 'F5': case KEY_F(1): case 'h': case '?': showHelp = true; break;
      case KEY_F(2): case 'C': case 'S': showSetup = true; break;
      case KEY_F(3): case '/':
         incSearchMode = true; incBuf[0] = '\0'; incCursor = 0;
         break;
      case KEY_F(4): case '\\':
         incFilterMode = true; incBuf[0] = '\0'; incCursor = 0;
         break;
      case KEY_F(5): toggleTree(); break;
      case KEY_F(6): case '>': case '.':
         buildSortPanel(); showSortMenu = true; break;
      case KEY_F(7): case ']': applyNice(-1); break;
      case KEY_F(8): case '[': applyNice(1); break;
      case KEY_F(9): case 'k':
         buildKillPanel(); showKillMenu = true; break;
      case KEY_F(10): case 'q':
         quitFlag = true;
         break;
      case 'K': s->hideKernelThreads = !s->hideKernelThreads; s->changed = 1; break;
      case 'H': s->hideUserlandThreads = !s->hideUserlandThreads; s->changed = 1; break;
      case 'O': s->hideRunningInContainer = !s->hideRunningInContainer; s->changed = 1; break;
      case 'p': s->showProgramPath = !s->showProgramPath; s->changed = 1; break;
      case 'm': s->showMergedCommand = !s->showMergedCommand; s->changed = 1; break;
      case '#': optNoMeters = !optNoMeters; break;
      case '+': case '=':
         /* expand tree */
         break;
      case '-':
         /* collapse tree */
         break;
      case '*':
         s->allBranchesCollapsed = !s->allBranchesCollapsed; s->changed = 1;
         break;
      case KEY_F(0): case 27:
         break;
      default: break;
   }
}

static void doSearchChar(int ch) {
   if (ch == 27) { incSearchMode = incFilterMode = false; incBuf[0] = '\0'; return; }
   if (ch == '\r' || ch == '\n' || ch == KEY_ENTER) {
      if (incFilterMode) {
         /* apply the filter */
         nFilterTerms = 0;
         if (incBuf[0]) filterTerms[0] = xStrdup(incBuf), nFilterTerms = 1;
      }
      incSearchMode = incFilterMode = false;
      return;
   }
   if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
      size_t n = strlen(incBuf);
      if (n > 0) incBuf[n-1] = '\0';
      if (incFilterMode) {
         nFilterTerms = 0;
         if (incBuf[0]) filterTerms[0] = xStrdup(incBuf), nFilterTerms = 1;
      }
      return;
   }
   if (ch >= 32 && ch < 127) {
      size_t n = strlen(incBuf);
      if (n < sizeof(incBuf) - 1) { incBuf[n] = (char)ch; incBuf[n+1] = '\0'; }
      if (incFilterMode) {
         nFilterTerms = 0;
         if (incBuf[0]) filterTerms[0] = xStrdup(incBuf), nFilterTerms = 1;
      } else {
         /* search: jump to the next match */
      }
   }
}

static void applyNice(int delta) {
   Panel* p = PP.panel;
   if (p->selected < 0 || p->selected >= p->size) return;
   Process* proc = (Process*)p->items[p->selected].data;
   int prio = proc->nice + delta;
   if (prio < -20) prio = -20;
   if (prio > 19) prio = 19;
   if (setpriority(PRIO_PROCESS, proc->pid, prio) == 0) {
      proc->nice = prio;
      PL.settings->changed = 1;
   }
}

static void sendSignal(int sig) {
   Panel* p = PP.panel;
   if (p->selected < 0 || p->selected >= p->size) return;
   Process* proc = (Process*)p->items[p->selected].data;
   kill(proc->pid, sig);
}

/* ---------------- main loop ---------------- */

static void applyScreen(int idx) {
   if (idx < 0 || idx >= PL.settings->nScreens) return;
   setScreenFields(idx, PL.settings->screenFields[idx], screenNFields[idx] ? screenNFields[idx] : 0);
   curScreen = idx;
   if (treeMode) {
      sortKeyCurrent = PL.settings->screenTreeSortKey[idx];
      sortDirCurrent = PL.settings->screenTreeSortDirection[idx];
   } else {
      sortKeyCurrent = PL.settings->screenSortKey[idx];
      sortDirCurrent = PL.settings->screenSortDirection[idx];
   }
}

int runHtop(Settings* settings) {
   PL.settings = settings;
   Panel* p = &PP.panel;
   Panel_init(p, 0, 0, COLS, LINES, "");
   Panel_init(&sortPanel, 0, 0, 16, LINES, "Sort by");
   Panel_init(&killPanel, 0, 0, 16, LINES, "Send signal:");
   applyScreen(0);
   Header_build(settings);
   int iterations = 0;
   bool quit = false;
   halfdelay(settings->delay);
   while (!quit) {
      ProcessList_update();
      drawAll(settings);
      if (maxIterations > 0 && ++iterations >= maxIterations) break;
      int ch = getch();
      if (ch == ERR) { continue; }
      if (ch == KEY_RESIZE) { continue; }
      if (showHelp) { showHelp = false; continue; }
      if (showSetup) { showSetup = false; continue; }
      handleKey(ch);
      if (quitFlag) quit = true;
   }
   if (settings->changed) Settings_write(settings);
   return 0;
}
CEOF
echo ok

