   { "filter", required_argument, NULL, 'F' },
   { "no-function-bar", no_argument, NULL, 1 },
   { "help", no_argument, NULL, 'h' },
   { "highlight-changes", optional_argument, NULL, 'H' },
   { "no-mouse", no_argument, NULL, 'M' },
   { "no-meters", no_argument, NULL, 2 },
   { "max-iterations", required_argument, NULL, 'n' },
   { "pid", required_argument, NULL, 'p' },
   { "readonly", no_argument, NULL, 3 },
   { "sort-key", required_argument, NULL, 's' },
   { "tree", no_argument, NULL, 't' },
   { "user", optional_argument, NULL, 'u' },
   { "no-unicode", no_argument, NULL, 'U' },
   { "version", no_argument, NULL, 'V' },
   { NULL, 0, NULL, 0 }
};

int main(int argc, char** argv) {
   setlocale(LC_ALL, "");
   Settings settings;
   Settings_init(&settings);
   initUser();
   PL.clockTicks = 100;
   FILE* f = fopen("/sys/fs/cgroup/cpu.max", "r"); (void)f;
   PL.pagesizeKB = 4;
   long ps = sysconf(_SC_PAGESIZE);
   if (ps > 0) PL.pagesizeKB = (int)(ps / 1024);
   PL.cpuCount = 1;
   { /* count cpus */
      FILE* cf = fopen("/proc/cpuinfo", "r");
      if (cf) {
         char buf[512];
         int n = 0;
         while (fgets(buf, sizeof(buf), cf)) {
            int id;
            if (sscanf(buf, "processor : %d", &id) == 1) n++;
         }
         fclose(cf);
         if (n > 0) PL.cpuCount = n;
      }
      if (PL.cpuCount <= 0) PL.cpuCount = sysconf(_SC_NPROCESSORS_ONLN);
      if (PL.cpuCount <= 0) PL.cpuCount = 1;
   }
   PL.cpuUser = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuUserPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuSystem = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuSystemPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuGuest = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuGuestPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuGuestNice = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuGuestNicePrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIdle = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIdlePrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIrq = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIrqPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuSoftIrq = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuSoftIrqPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuSteal = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuStealPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIowait = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuIowaitPrev = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuNice = calloc(PL.cpuCount + 1, sizeof(u64));
   PL.cpuNicePrev = calloc(PL.cpuCount + 1, sizeof(u64));
   gettimeofday(&PL.lastUpdate, NULL);
   PL.bootTimeSecs = time(NULL) - 1;

   int opt;
   bool showVersion = false, showHelpScreen = false;
   bool sortHelp = false;
   char* sortKeyArg = NULL;
   optind = 1;
   while ((opt = getopt_long(argc, argv, "Cd:F:hH::Mn:p:s:tu::UV", longOpts, NULL)) != -1) {
      switch (opt) {
         case 'C': optMonochrome = true; settings.colorScheme = 1; break;
         case 'd': {
            int v = atoi(optarg);
            if (v < 1) v = 1;
            if (v > 100) v = 100;
            settings.delay = v;
            break;
         }
         case 'F': parseFilter(optarg); break;
         case 1: optNoFunctionBar = true; settings.hideFunctionBar = 1; break;
         case 'h': showHelpScreen = true; break;
         case 'H':
            optHighlightChanges = true;
            if (optarg) optHighlightDelay = atoi(optarg);
            settings.highlightChanges = 1;
            settings.highlightChangesDelaySecs = optHighlightDelay;
            break;
         case 'M': optNoMouse = true; settings.enableMouse = 0; break;
         case 2: optNoMeters = true; break;
         case 'n': {
            char* end = NULL;
            long v = strtol(optarg, &end, 10);
            if (end == optarg || *end != '\0') {
               fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", optarg);
               return 1;
            }
            if (v <= 0) {
               fprintf(stderr, "Error: maximum iteration count must be positive.\n");
               return 1;
            }
            maxIterations = (int)v;
            break;
         }
         case 'p': parsePidList(optarg); break;
         case 3: optReadonly = true; settings.readonly = 1; break;
         case 's':
            if (strcmp(optarg, "help") == 0) { sortHelp = true; }
            else {
               int fi = fieldIndexByName(optarg);
               if (fi < 0) {
                  fprintf(stderr, "Error: invalid column \"%s\".\n", optarg);
                  return 1;
               }
               sortKeyArg = optarg;
               setSortKey((ProcessField)fi, 0);
            }
            break;
         case 't': optTree = true; settings.treeView = 1; break;
