{"command": "cd $HOME/htop/src && cat >> meter.c <<'CEOF'

int Meter_height(Meter* m) { return m->height; }
CEOF
cat >> ui.c <<'CEOF'

/* ---------------- process list update ---------------- */

static bool listVisible(Process* p) {
   if (PL.settings->hideKernelThreads && p->isKernelThread) return false;
   if (PL.settings->hideUserlandThreads && p->isUserlandThread) return false;
   if (PL.settings->hideRunningInContainer && p->isContainerProcess) return false;
   if (PL.settings->shadowOtherUsers && p->st_uid != myUid) return false;
   if (filterUserSet && p->st_uid != filterUid) return false;
   if (nPidList > 0) {
      bool found = false;
      for (int i = 0; i < nPidList; i++) if (pidList[i] == p->pid) { found = true; break; }
      if (!found) return false;
   }
   if (nFilterTerms > 0) {
      const char* cmd = p->cmdline ? p->cmdline : (p->comm ? p->comm : "");
      bool any = false;
      for (int i = 0; i < nFilterTerms; i++) {
         if (strcasestr(cmd, filterTerms[i])) { any = true; break; }
      }
      if (!any) return false;
   }
   return true;
}

void ProcessList_update(void) {
   struct timeval now;
   gettimeofday(&now, NULL);
   double interval = (double)(now.tv_sec - PL.lastUpdate.tv_sec) + (double)(now.tv_usec - PL.lastUpdate.tv_usec) / 1e6;
   if (interval < 0.001) interval = 0.001;
   for (int i = 0; i < PL.cpuCount; i++) {
      PL.cpuUserPrev[i] = PL.cpuUser[i]; PL.cpuSystemPrev[i] = PL.cpuSystem[i];
      PL.cpuGuestPrev[i] = PL.cpuGuest[i]; PL.cpuGuestNicePrev[i] = PL.cpuGuestNice[i];
      PL.cpuIdlePrev[i] = PL.cpuIdle[i]; PL.cpuIrqPrev[i] = PL.cpuIrq[i];
      PL.cpuSoftIrqPrev[i] = PL.cpuSoftIrq[i]; PL.cpuStealPrev[i] = PL.cpuSteal[i];
      PL.cpuIowaitPrev[i] = PL.cpuIowait[i]; PL.cpuNicePrev[i] = PL.cpuNice[i];
   }
   PL.lastUpdate = now;
   readSystemInfo();
   PL.totalTasks = 0; PL.userlandThreads = 0; PL.kernelThreads = 0; PL.runningTasks = 0;
   DIR* d = opendir("/proc");
   if (!d) return;
   struct dirent* e;
   Process* found[4096];
   int nFound = 0;
   while ((e = readdir(d)) != NULL) {
      if (e->d_name[0] < '0' || e->d_name[0] > '9') continue;
      int pid = atoi(e->d_name);
      if (pid <= 0) continue;
      if (nPidList > 0) {
         bool ok = false;
         for (int i = 0; i < nPidList; i++) if (pidList[i] == pid) { ok = true; break; }
         if (!ok) continue;
      }
      if (nFound >= 4096) break;
      Process* p = NULL;
      for (int i = 0; i < PL.count; i++) if (PL.procs[i].pid == pid) { p = &PL.procs[i]; break; }
      bool isNew = false;
      if (!p) {
         for (int i = 0; i < PL.count; i++) {
            if (!PL.procs[i].updated) { p = &PL.procs[i]; memset(p, 0, sizeof(*p)); p->pid = pid; isNew = true; break; }
         }
         if (!p && PL.count < MAX_PROCS) { p = &PL.procs[PL.count]; PL.count++; memset(p, 0, sizeof(*p)); p->pid = pid; isNew = true; }
      }
      if (!p) continue;
      p->updated = true;
      p->prev_utime = p->utime; p->prev_stime = p->stime;
      p->prev_rbytes = p->rbytes; p->prev_wbytes = p->wbytes; p->prev_cnclwb = p->cnclwb;
      p->prev_syscr = p->syscr; p->prev_syscw = p->syscw;
      p->prev_minflt = p->minflt; p->prev_cminflt = p->cminflt;
      p->prev_majflt = p->majflt; p->prev_cmajflt = p->cmajflt;
      if (!readStat(pid, p)) { p->updated = false; continue; }
      readStatm(p);
      readIo(p);
      readStatus(p);
      readMisc(p);
      if (isNew || PL.settings->updateProcessNames) readLinks(p);
      struct passwd* pw = getpwuid((uid_t)p->st_uid);
      char ub[64];
      if (pw && pw->pw_name) snprintf(ub, sizeof(ub), "%s", pw->pw_name);
      else snprintf(ub, sizeof(ub), "%d", p->st_uid);
      setStr(&p->user, ub);
      p->isRoot = (p->st_uid == 0);
      p->isUserlandThread = (p->tgid && p->tgid != p->pid);
      p->isContainerProcess = false;
      p->percent_mem = PL.memTotal ? 100.0 * (double)p->m_resident / (double)PL.memTotal : 0;
      double iv = interval;
      p->io_read_rate = (u64)(((double)(p->rbytes - p->prev_rbytes)) / iv);
      p->io_write_rate = (u64)(((double)(p->wbytes - p->prev_wbytes)) / iv);
      p->io_rate = p->io_read_rate + p->io_write_rate;
      if (p->tty_nr == 0) snprintf(p->tty, sizeof(p->tty), "?");
      else {
         int major = (p->tty_nr >> 8) & 0xfff;
         int minor = p->tty_nr & 0xff;
         if (major == 136) snprintf(p->tty, sizeof(p->tty), "pts/%d", minor);
         else if (major == 4) {
            if (minor < 64) snprintf(p->tty, sizeof(p->tty), "tty%d", minor);
            else snprintf(p->tty, sizeof(p->tty), "ttyS%d", minor - 64);
         } else snprintf(p->tty, sizeof(p->tty), "?");
      }
      found[nFound++] = p;
   }
   closedir(d);
   double periodTicks = interval * PL.clockTicks;
   if (periodTicks < 1) periodTicks = 1;
   for (int i = 0; i < nFound; i++) {
      Process* p = found[i];
      u64 dUtime = p->utime - p->prev_utime;
      u64 dStime = p->stime - p->prev_stime;
      p->percent_cpu = 100.0 * (double)(dUtime + dStime) / periodTicks;
      if (p->percent_cpu < 0) p->percent_cpu = 0;
      p->percent_norm_cpu = p->percent_cpu / (PL.cpuCount ? PL.cpuCount : 1);
      if (p->state == 'R') PL.runningTasks++;
      PL.totalTasks++;
      if (p->isUserlandThread) PL.userlandThreads++;
      else if (p->isKernelThread) PL.kernelThreads++;
   }
   PL.sortKey = (ProcessField)sortKeyCurrent;
   PL.sortDirection = sortDirCurrent;
   qsort(found, nFound, sizeof(Process*), (int (*)(const void*, const void*))Process_compare);
   Panel_clear(PP.panel);
   for (int i = 0; i < nFound; i++) {
      Process* p = found[i];
      if (!listVisible(p)) continue;
      Panel_add(PP.panel, p, NULL);
   }
}
CEOF
gcc -o /tmp/htop_test -O1 htop.h fields.c settings.c crt.c process.c meter.c ui.c main.c -lncursesw -ltinfo 2>&1 | grep -E 'error|undefined' | head -10"}

